window.SAGE_CHAPTERS = (window.SAGE_CHAPTERS || []).concat([
{
 id: "sk-1", sage: "shukracharya", n: 1, order: 301, date: "2026-10-17",
 title: "Son of Bhṛgu", titleTe: "భృగు పుత్రుడు",
 src: "Purāṇas · Mahābhārata",
 who: ["bhrigu", "brihaspati", "brahma"],
 pages: [
  [
   ["p", "Among the sages born from Brahmā's mind was {bhrigu|Bhṛgu}, one of the greatest and boldest of all ṛṣis. His family, the Bhārgavas, would give the world fierce and brilliant sons — Ṛcīka, Jamadagni, Paraśurāma, Aurva. But the most famous of all was Bhṛgu's son Uśanā, whom the world knows as Śukrācārya, “the teacher Śukra.”", "బ్రహ్మ మానస పుత్రులలో {bhrigu|భృగువు} ఒకరు — ఋషులందరిలోనూ అత్యంత గొప్పవారిలో, సాహసవంతులలో ఒకరు. ఆయన వంశం — భార్గవులు — లోకానికి ఉగ్రులైన, తేజస్వులైన కుమారులను ఇచ్చింది: ఋచీకుడు, జమదగ్ని, పరశురాముడు, ఔర్వుడు. కానీ అందరిలోనూ అత్యంత ప్రసిద్ధుడు భృగువు కుమారుడు ఉశనుడు — లోకం ఆయనను శుక్రాచార్యుడు అంటుంది."],
   ["p", "He has many names. Uśanā, his birth name. Kāvya, “the son of the poet.” Bhārgava, “of Bhṛgu's family.” Śukra, “the bright one,” the name he got later in a strange way. And Daitya-guru, “guru of the demons.” Most Purāṇas call him Bhṛgu's son; one passage of the Mahābhārata calls him Bhṛgu's grandson, the son of a sage named Kavi — which may be why he is called Kāvya.", "ఆయనకు ఎన్నో పేర్లు. ఉశనుడు — జన్మనామం. కావ్యుడు — “కవి కుమారుడు.” భార్గవుడు — “భృగు వంశీయుడు.” శుక్రుడు — “ప్రకాశించేవాడు”; ఈ పేరు తర్వాత ఒక విచిత్రమైన విధంగా వచ్చింది. దైత్యగురువు — “రాక్షసుల గురువు.” చాలా పురాణాలు ఆయనను భృగువు కుమారుడని చెబుతాయి; మహాభారతంలో ఒక చోట భృగువు మనవడని, కవి అనే మహర్షి కుమారుడని చెబుతుంది — అందుకే కావ్యుడు అనే పేరు వచ్చి ఉండవచ్చు."],
   ["p", "He was a poet, a master of the Vedas, a great teacher of statecraft — and he would come to hold a secret that no other being in the three worlds had: the Mṛtasañjīvanī, the knowledge that brings the dead back to life.", "ఆయన కవి, వేదవేత్త, రాజనీతిలో గొప్ప ఆచార్యుడు — ముల్లోకాలలో మరెవరికీ లేని ఒక రహస్యం ఆయనకు సొంతమవుతుంది: మృతసంజీవని — చనిపోయినవారిని బతికించే విద్య."]
  ],
  [
   ["h", "Two Students, One Teacher", "ఒకే గురువు, ఇద్దరు శిష్యులు"],
   ["p", "It is said that as a boy Uśanā was sent to study with the great sage Aṅgiras. Studying beside him was Aṅgiras' own son, {brihaspati|Bṛhaspati}. Both boys were brilliant. But Uśanā felt that Aṅgiras taught his own son more carefully, more lovingly, than him. Hurt, he left, studied under other teachers, and went on to do tapas on his own.", "చిన్నతనంలో ఉశనుణ్ణి అంగిరస మహర్షి దగ్గర చదువుకోవడానికి పంపారని అంటారు. అతని పక్కనే చదువుకున్నది అంగిరసుని సొంత కుమారుడు {brihaspati|బృహస్పతి}. ఇద్దరూ మేధావులే. కానీ అంగిరసుడు తనకంటే తన కొడుకుకే ఎక్కువ శ్రద్ధగా, ప్రేమగా బోధిస్తున్నాడని ఉశనునికి అనిపించింది. బాధపడి వెళ్ళిపోయి, వేరే గురువుల దగ్గర చదువుకుని, సొంతంగా తపస్సు చేశాడు."],
   ["p", "Bṛhaspati became the guru of the devas. And Uśanā became the guru of their half-brothers and rivals — the asuras, the sons of Diti and Danu. From then on, every war between gods and demons was also a contest between these two old classmates, Bṛhaspati and Śukra — Jupiter and Venus.", "బృహస్పతి దేవతలకు గురువయ్యాడు. ఉశనుడు వారి సవతి సోదరులకు, ప్రత్యర్థులకు — దితి, దనువుల కుమారులైన అసురులకు — గురువయ్యాడు. అప్పటి నుండి దేవాసుర యుద్ధాలన్నీ ఈ ఇద్దరు పాత సహపాఠుల — బృహస్పతి, శుక్రుల — మధ్య పోటీ కూడా. గురుడు, శుక్రుడు."],
   ["dyk", "👨‍👩‍👦", "Devas and asuras are family. Both are children of the sage Kaśyapa — the devas by his wife Aditi, the daityas by Diti, the dānavas by Danu. They are cousins who fight forever over the three worlds.", "దేవతలూ అసురులూ ఒకే కుటుంబం. ఇద్దరూ కశ్యప మహర్షి సంతానమే — దేవతలు అదితి వల్ల, దైత్యులు దితి వల్ల, దానవులు దనువు వల్ల. ముల్లోకాల కోసం ఎప్పటికీ పోట్లాడుకునే దాయాదులు వాళ్ళు."]
  ],
  [
   ["h", "Why the Demons?", "రాక్షసులనే ఎందుకు?"],
   ["p", "Why would a great sage, son of Bhṛgu, choose to teach the asuras? The texts give no single answer, but they show us his character. Śukra was loyal. Once he accepted students, he stood by them — through victory and defeat, even against the gods, even against Viṣṇu himself. He scolded them, cursed them when they disobeyed, and forgave them when they returned. The asuras loved and feared him, and they called him simply “the Guru.”", "భృగువు కుమారుడైన మహర్షి అసురులకే ఎందుకు బోధించాలనుకున్నాడు? గ్రంథాలు ఒకే జవాబు ఇవ్వవు; కానీ ఆయన స్వభావాన్ని చూపిస్తాయి. శుక్రుడు విశ్వాసపాత్రుడు. శిష్యులను ఒకసారి స్వీకరిస్తే — గెలుపులోనూ ఓటమిలోనూ, దేవతలకు వ్యతిరేకంగానూ, సాక్షాత్తు విష్ణువుకు వ్యతిరేకంగానూ — వారి పక్షానే నిలిచాడు. వారిని మందలించాడు, మాట వినకపోతే శపించాడు, తిరిగి వస్తే క్షమించాడు. అసురులు ఆయనను ప్రేమించారు, భయపడ్డారు; ఆయనను కేవలం “గురువు” అని పిలిచేవారు."],
   ["p", "He also had a long memory for wrongs done to his family — and, as we will see in the next chapter, the gods had done one that he never forgot.", "తన కుటుంబానికి జరిగిన అన్యాయాలను ఆయన ఎప్పటికీ మరిచిపోలేదు — తర్వాతి అధ్యాయంలో చూడబోతున్నట్టు, దేవతలు ఆయనకు మరిచిపోలేని ఒక అన్యాయం చేశారు."],
   ["src", "Bhāgavata Purāṇa 4.1 and 6.18; Mahābhārata, Ādi Parva, chapter 60 (Critical Edition) for his lineage. The story of Uśanā and Bṛhaspati studying under Aṅgiras is a traditional telling, not found in the oldest texts.", "భాగవత పురాణం 4.1, 6.18; వంశం కోసం మహాభారతం, ఆదిపర్వం, 60వ అధ్యాయం (విమర్శనాత్మక ప్రతి). ఉశనుడు, బృహస్పతి అంగిరసుని దగ్గర చదువుకున్న కథ సంప్రదాయ కథనం; అత్యంత ప్రాచీన గ్రంథాలలో లేదు."]
  ]
 ],
 remember: [
  ["Śukrācārya, also called Uśanā and Kāvya, is the son of the sage {bhrigu|Bhṛgu}.", "ఉశనుడు, కావ్యుడు అని కూడా పిలవబడే శుక్రాచార్యుడు {bhrigu|భృగు} మహర్షి కుమారుడు."],
  ["He became guru of the asuras; his rival {brihaspati|Bṛhaspati} was guru of the devas.", "ఆయన అసురుల గురువయ్యాడు; ఆయన ప్రత్యర్థి {brihaspati|బృహస్పతి} దేవగురువు."],
  ["He was fiercely loyal to his students.", "శిష్యుల పట్ల ఆయనకు అచంచలమైన విశ్వాసం."]
 ],
 think: ["Uśanā felt his teacher loved his own son more. How do you think that feeling shaped the rest of his life?", "తన గురువు సొంత కొడుకునే ఎక్కువ ప్రేమిస్తున్నాడని ఉశనునికి అనిపించింది. ఆ భావన ఆయన మిగతా జీవితాన్ని ఎలా ప్రభావితం చేసి ఉంటుందని మీరనుకుంటున్నారు?"]
},
{
 id: "sk-2", sage: "shukracharya", n: 2, order: 302, date: "2026-10-17",
 title: "The Secret of Mṛtasañjīvanī", titleTe: "మృతసంజీవని రహస్యం",
 src: "Matsya Purāṇa · Devī Bhāgavatam",
 who: ["shiva", "kavyamata", "vishnu", "bhrigu", "jayanti", "brihaspati", "prahlada"],
 pages: [
  [
   ["p", "The devas and asuras were at war again, and the asuras were losing badly. Śukra told them: “Hold back from fighting for a while. I will go to {shiva|Śiva} and win a mantra that will make you invincible.” He told the asuras to wait quietly, wearing bark like hermits, at his father Bhṛgu's āśrama, under the protection of his mother.", "దేవాసురుల మధ్య మళ్ళీ యుద్ధం జరుగుతోంది; అసురులు ఘోరంగా ఓడిపోతున్నారు. శుక్రుడు వారితో అన్నాడు: “కొంతకాలం యుద్ధం ఆపండి. నేను {shiva|శివుని} దగ్గరికి వెళ్ళి మిమ్మల్ని అజేయులను చేసే మంత్రం సాధిస్తాను.” తాపసుల్లా నారబట్టలు ధరించి, తన తండ్రి భృగువు ఆశ్రమంలో, తన తల్లి రక్షణలో నిశ్శబ్దంగా ఉండమని అసురులకు చెప్పాడు."],
   ["p", "Then he began the most terrible tapas in the Purāṇas. For a thousand years he hung upside down from a tree, breathing nothing but the smoke of a fire of chaff burning beneath him. He did not eat. He did not move.", "తర్వాత పురాణాలలోనే అత్యంత భయంకరమైన తపస్సు మొదలుపెట్టాడు. వెయ్యేళ్ళు చెట్టుకు తలకిందులుగా వేలాడుతూ, కింద మండుతున్న ఊక పొగ తప్ప మరేమీ పీల్చకుండా ఉన్నాడు. తినలేదు. కదలలేదు."]
  ],
  [
   ["h", "Bhṛgu's Curse on Viṣṇu", "విష్ణువుకు భృగు శాపం"],
   ["p", "While Śukra was away, the devas found the asuras hiding at Bhṛgu's āśrama and attacked. Śukra's mother, {kavyamata|Kāvyamātā}, would not let guests be killed in her home. With the power of her tapas she froze Indra where he stood and protected the asuras. Indra cried out to {vishnu|Viṣṇu} for help. And Viṣṇu, to save the devas, threw his discus and cut off her head.", "శుక్రుడు దూరంగా ఉన్నప్పుడు దేవతలు భృగు ఆశ్రమంలో దాక్కున్న అసురులను కనుగొని దాడి చేశారు. తన ఇంట్లో అతిథులను చంపనివ్వనని శుక్రుని తల్లి {kavyamata|కావ్యమాత} అడ్డుపడింది. తన తపశ్శక్తితో ఇంద్రుణ్ణి ఉన్నచోటే స్తంభింపజేసి అసురులను కాపాడింది. ఇంద్రుడు సహాయం కోసం {vishnu|విష్ణువును} వేడుకున్నాడు. దేవతలను కాపాడడానికి విష్ణువు తన చక్రాన్ని ప్రయోగించి ఆమె తల నరికేశాడు."],
   ["p", "{bhrigu|Bhṛgu} came home and saw his wife killed. In grief and fury he cursed Viṣṇu himself: “You have killed a woman, which must never be done. For this, you will be born again and again on earth, in human wombs, and suffer human sorrows.” Then Bhṛgu sprinkled water from his kamaṇḍalu and, by his tapas, brought his wife back to life.", "{bhrigu|భృగువు} ఇంటికి వచ్చి చంపబడిన భార్యను చూశాడు. దుఃఖంతో, కోపంతో సాక్షాత్తు విష్ణువునే శపించాడు: “ఎప్పుడూ చేయకూడని పని చేశావు — స్త్రీని చంపావు. అందుకు నువ్వు మళ్ళీ మళ్ళీ భూమి మీద మానవ గర్భాలలో పుట్టి మానవ దుఃఖాలు అనుభవిస్తావు.” తర్వాత కమండలంలోని నీళ్ళు చల్లి తన తపశ్శక్తితో భార్యను బతికించాడు."],
   ["dyk", "🔁", "The Matsya and Padma Purāṇas say this is one reason Viṣṇu takes so many avatāras on earth — as Rāma, as Kṛṣṇa — and goes through grief like a human: Bhṛgu's curse. Viṣṇu accepted it for the good of the world.", "విష్ణువు భూమి మీద ఇన్ని అవతారాలు ఎత్తడానికి — రాముడిగా, కృష్ణుడిగా — మనిషిలా దుఃఖాన్ని అనుభవించడానికి ఒక కారణం ఈ భృగు శాపమేనని మత్స్య, పద్మ పురాణాలు చెబుతాయి. లోకహితం కోసం విష్ణువు దాన్ని స్వీకరించాడు."]
  ],
  [
   ["h", "Jayantī", "జయంతి"],
   ["p", "Indra was terrified of what Śukra would do with Śiva's mantra. So he sent his own daughter, {jayanti|Jayantī}, to the forest. “Serve him. Win his heart. Keep him from returning to the asuras.” Jayantī went and served Śukra with complete devotion — fanning him, bringing water, sitting silently beside him — for years, while he hung in tapas.", "శివుని మంత్రంతో శుక్రుడు ఏమి చేస్తాడోనని ఇంద్రుడు భయపడ్డాడు. అందుకే తన సొంత కుమార్తె {jayanti|జయంతిని} అడవికి పంపాడు. “ఆయనకు సేవ చెయ్యి. ఆయన మనసు గెలుచుకో. అసురుల దగ్గరికి తిరిగి వెళ్ళకుండా ఆపు.” జయంతి వెళ్ళి — విసురుతూ, నీళ్ళు తెస్తూ, పక్కనే మౌనంగా కూర్చుంటూ — ఆయన తపస్సులో వేలాడుతున్నన్ని ఏళ్ళూ సంపూర్ణ భక్తితో సేవ చేసింది."],
   ["p", "At the end of the thousand years Śiva appeared and gave Śukra what no one else had: the Mṛtasañjīvanī vidyā — the knowledge to bring the dead back to life. Then Śukra opened his eyes and saw Jayantī. “Who are you, who served me so faithfully? Ask for anything.” “I am Indra's daughter,” she said. “I wish to be your wife.” He agreed — and the two lived together for ten years, hidden from all the worlds by Śukra's power. Their daughter was Devayānī.", "వెయ్యేళ్ళ చివర శివుడు ప్రత్యక్షమై మరెవరికీ లేనిది శుక్రునికి ఇచ్చాడు: మృతసంజీవని విద్య — చనిపోయినవారిని బతికించే జ్ఞానం. అప్పుడు శుక్రుడు కళ్ళు తెరిచి జయంతిని చూశాడు. “ఇంత విశ్వాసంగా నాకు సేవ చేసిన నువ్వెవరు? ఏది కావాలన్నా అడుగు.” “నేను ఇంద్రుని కుమార్తెను,” అంది. “మీ భార్యను కావాలని కోరుకుంటున్నాను.” ఆయన ఒప్పుకున్నాడు — శుక్రుని మాయాశక్తితో అన్ని లోకాలకూ కనిపించకుండా ఇద్దరూ పదేళ్ళు కలిసి జీవించారు. వారి కుమార్తె దేవయాని."]
  ],
  [
   ["h", "Two Śukras", "ఇద్దరు శుక్రులు"],
   ["p", "Meanwhile, {brihaspati|Bṛhaspati} saw his chance. He took Śukra's exact form and went to the asuras. “I am back, my children,” he said. For ten years the false Śukra taught them — and slowly turned them away from the Vedas and from their strength.", "ఈలోగా {brihaspati|బృహస్పతి} తనకు అవకాశం దొరికిందనుకున్నాడు. అచ్చం శుక్రుని రూపం దాల్చి అసురుల దగ్గరికి వెళ్ళాడు. “పిల్లలారా, నేను తిరిగి వచ్చాను,” అన్నాడు. పదేళ్ళు ఆ నకిలీ శుక్రుడు వారికి బోధించాడు — నెమ్మదిగా వారిని వేదాల నుండి, వారి బలం నుండి దూరం చేశాడు."],
   ["p", "When the real Śukra came back, he found another Śukra sitting among his students. “That is Bṛhaspati! He is deceiving you!” he cried. But the asuras looked from one to the other, and believed the one they had been with for ten years. They drove the real Śukra away.", "నిజమైన శుక్రుడు తిరిగి వచ్చేసరికి తన శిష్యుల మధ్య మరో శుక్రుడు కూర్చుని ఉన్నాడు. “అతను బృహస్పతి! మిమ్మల్ని మోసం చేస్తున్నాడు!” అని అరిచాడు. కానీ అసురులు ఇద్దరినీ చూసి, పదేళ్ళుగా తమతో ఉన్నవాణ్ణే నమ్మారు. నిజమైన శుక్రుణ్ణి తరిమేశారు."],
   ["p", "Śukra was furious. “You have abandoned your true guru. You will lose, and be destroyed!” As soon as the curse was spoken, Bṛhaspati, his work done, vanished. The asuras realized their mistake and, led by the wise {prahlada|Prahlāda}, came begging forgiveness. Śukra could not take back the curse — the asuras would be defeated for a time — but he forgave them, and came back as their guru, now holding the secret of Mṛtasañjīvanī.", "శుక్రునికి పట్టరాని కోపం వచ్చింది. “మీ నిజమైన గురువును వదిలేశారు. మీరు ఓడిపోతారు, నశిస్తారు!” శాపం వెలువడగానే, తన పని పూర్తయిందని బృహస్పతి మాయమయ్యాడు. అసురులు తమ తప్పు గ్రహించి, జ్ఞాని అయిన {prahlada|ప్రహ్లాదుని} నాయకత్వంలో క్షమాపణ కోరుతూ వచ్చారు. శుక్రుడు శాపాన్ని వెనక్కి తీసుకోలేడు — కొంతకాలం అసురులు ఓడిపోక తప్పదు — కానీ వారిని క్షమించి, మృతసంజీవని రహస్యంతో మళ్ళీ వారి గురువుగా తిరిగి వచ్చాడు."],
   ["src", "Matsya Purāṇa, chapter 47; Devī Bhāgavatam, Book 4, chapters 10–13; Padma Purāṇa (Bhṛgu's curse). The tellings differ in details.", "మత్స్య పురాణం, 47వ అధ్యాయం; దేవీ భాగవతం, 4వ స్కంధం, 10–13 అధ్యాయాలు; పద్మ పురాణం (భృగు శాపం). వివరాలలో కథనాలు భిన్నంగా ఉంటాయి."]
  ]
 ],
 remember: [
  ["Śukra did tapas upside down, breathing smoke, for a thousand years to win the Mṛtasañjīvanī from Śiva.", "శివుని నుండి మృతసంజీవని పొందడానికి శుక్రుడు తలకిందులుగా, పొగ పీలుస్తూ వెయ్యేళ్ళు తపస్సు చేశాడు."],
  ["Viṣṇu killed his mother; {bhrigu|Bhṛgu} cursed Viṣṇu to be born many times as a human.", "విష్ణువు ఆయన తల్లిని చంపాడు; {bhrigu|భృగువు} విష్ణువును ఎన్నోసార్లు మనిషిగా పుట్టమని శపించాడు."],
  ["{brihaspati|Bṛhaspati} took Śukra's form and fooled the asuras; Śukra cursed them, then forgave them.", "{brihaspati|బృహస్పతి} శుక్రుని రూపం దాల్చి అసురులను మోసం చేశాడు; శుక్రుడు వారిని శపించి, తర్వాత క్షమించాడు."]
 ],
 think: ["The asuras trusted the teacher who had been with them longest, not the true one. How can you tell the real thing from a copy, when they look the same?", "అసురులు నిజమైన గురువును కాకుండా తమతో ఎక్కువ కాలం ఉన్నవాణ్ణి నమ్మారు. రెండూ ఒకేలా కనిపిస్తున్నప్పుడు నిజమైనదాన్ని నకిలీ నుండి ఎలా వేరు చేయాలి?"]
},
{
 id: "sk-3", sage: "shukracharya", n: 3, order: 303, date: "2026-10-17",
 title: "Swallowed by Śiva", titleTe: "శివుడు మింగిన ముని",
 src: "Mahābhārata, Śānti Parva · Śiva Purāṇa",
 who: ["kubera", "shiva", "parvati"],
 pages: [
  [
   ["p", "After the war, Yudhiṣṭhira asked Bhīṣma two questions: “Why did the wise Uśanā take the side of the asuras against the gods? And why is he called Śukra?” Bhīṣma answered with a story — one of the strangest in the Mahābhārata.", "యుద్ధం తర్వాత ధర్మరాజు భీష్ముణ్ణి రెండు ప్రశ్నలు అడిగాడు: “జ్ఞాని అయిన ఉశనుడు దేవతలకు వ్యతిరేకంగా అసురుల పక్షం ఎందుకు వహించాడు? ఆయనకు శుక్రుడు అనే పేరు ఎందుకు వచ్చింది?” భీష్ముడు ఒక కథతో జవాబిచ్చాడు — మహాభారతంలోని అత్యంత విచిత్రమైన కథలలో ఒకటి."],
   ["p", "Uśanā, by the power of his yoga, once entered the body of {kubera|Kubera}, the lord of wealth, and from inside took control of all his treasure — and carried it away for the asuras. Kubera was helpless and furious. He went to his friend {shiva|Śiva}: “The sage Uśanā has robbed me by yoga, and gone.”", "ఉశనుడు ఒకసారి తన యోగశక్తితో ధనాధిపతి {kubera|కుబేరుని} శరీరంలోకి ప్రవేశించి, లోపలి నుండి అతని సంపదనంతా వశం చేసుకుని — అసురుల కోసం తీసుకుపోయాడు. కుబేరుడు నిస్సహాయుడై కోపంతో తన మిత్రుడు {shiva|శివుని} దగ్గరికి వెళ్ళాడు: “ఉశనుడు యోగబలంతో నన్ను దోచుకుని వెళ్ళిపోయాడు.”"]
  ],
  [
   ["p", "Śiva's eyes grew red with anger. He seized his trident and went looking for Uśanā. Uśanā saw him coming from far away and understood he could not escape. So he did a clever thing: he jumped onto the very tip of Śiva's trident and clung there, where Śiva could not strike him with it. Śiva bent the trident with his hand — and that bent weapon, it is said, became the bow Pināka.", "శివుని కళ్ళు కోపంతో ఎర్రబడ్డాయి. త్రిశూలం పట్టుకుని ఉశనుణ్ణి వెతుకుతూ వెళ్ళాడు. శివుడు దూరం నుండి వస్తుండడం చూసి తప్పించుకోలేనని ఉశనుడు గ్రహించాడు. అందుకే ఒక తెలివైన పని చేశాడు: సాక్షాత్తు శివుని త్రిశూలపు కొనకే ఎగిరి అతుక్కున్నాడు — అక్కడ ఉంటే శివుడు దానితో కొట్టలేడు. శివుడు త్రిశూలాన్ని చేత్తో వంచాడు — ఆ వంగిన ఆయుధమే పినాకమనే ధనుస్సు అయిందని అంటారు."],
   ["p", "Then Śiva plucked Uśanā off the trident with his hand — and swallowed him whole.", "తర్వాత శివుడు చేత్తో ఉశనుణ్ణి త్రిశూలం నుండి లాగి — మొత్తంగా మింగేశాడు."],
   ["p", "Śiva then entered the waters and stood there in tapas for an immensely long time. Inside Śiva's body, Uśanā wandered, unable to find a way out, praising Śiva constantly. At last, when Śiva's tapas was complete, Uśanā begged to be let out. Śiva said, “Come out through my generative organ.” And Uśanā came out of Śiva's body as his seed — śukra.", "తర్వాత శివుడు నీటిలోకి ప్రవేశించి ఎంతో దీర్ఘకాలం తపస్సులో నిలబడ్డాడు. శివుని శరీరం లోపల ఉశనుడు బయటపడే దారి దొరకక తిరుగుతూ, నిరంతరం శివుణ్ణి స్తుతిస్తూ ఉన్నాడు. చివరికి శివుని తపస్సు పూర్తయ్యాక బయటకు వదలమని ఉశనుడు వేడుకున్నాడు. “నా జననేంద్రియం ద్వారా బయటకు రా,” అన్నాడు శివుడు. ఉశనుడు శివుని శరీరం నుండి ఆయన వీర్యంగా — శుక్రంగా — బయటకు వచ్చాడు."]
  ],
  [
   ["p", "That, says Bhīṣma, is how he got the name Śukra. And because he had come out of Śiva's body, he was now in a way Śiva's son — and so he could never be destroyed.", "అలా ఆయనకు శుక్రుడు అనే పేరు వచ్చిందని భీష్ముడు చెబుతాడు. శివుని శరీరం నుండి బయటకు వచ్చాడు కాబట్టి ఇప్పుడు ఒక విధంగా శివుని కుమారుడు — అందుకే ఆయనను ఎప్పటికీ నాశనం చేయలేరు."],
   ["p", "Śiva, seeing him come out shining, raised his trident in anger again. But {parvati|Pārvatī} stepped between them. “He came out of your body. He is my son now. You must not kill him.” Śiva laughed, and lowered the trident. “Go wherever you wish,” he told Śukra. Śukra bowed to both of them and went. From then on he was called the son of Śiva and Pārvatī.", "ప్రకాశిస్తూ బయటకు వచ్చిన ఆయనను చూసి శివుడు మళ్ళీ కోపంతో త్రిశూలం ఎత్తాడు. కానీ {parvati|పార్వతీదేవి} మధ్యలో నిలబడింది. “ఇతను మీ శరీరం నుండి వచ్చాడు. ఇప్పుడు నా కొడుకు. మీరు ఇతన్ని చంపకూడదు.” శివుడు నవ్వి త్రిశూలం దించాడు. “నీ ఇష్టం వచ్చిన చోటికి వెళ్ళు,” అని శుక్రునితో అన్నాడు. శుక్రుడు ఇద్దరికీ నమస్కరించి వెళ్ళిపోయాడు. అప్పటి నుండి ఆయనను శివపార్వతుల కుమారుడు అని కూడా అంటారు."],
   ["more", "Another swallowing — the Śiva Purāṇa", "మరో మింగుడు — శివ పురాణం", "Śukra and the war with Andhaka", "శుక్రుడు, అంధకాసుర యుద్ధం", [
     ["p", "The Śiva Purāṇa tells a second story. In Śiva's war with the asura Andhaka, every time Śiva's army killed asuras, Śukra brought them back to life with the Mṛtasañjīvanī — the war could never end. So Śiva sent his bull Nandi, who caught Śukra and carried him to Śiva. Śiva swallowed him. Without their guru, the asuras could no longer be revived, and Andhaka was defeated. Śukra stayed inside Śiva, praising him, until Śiva released him — again as his seed, and again he was named Śukra.", "శివ పురాణం రెండవ కథ చెబుతుంది. అంధకాసురునితో శివుని యుద్ధంలో, శివుని సైన్యం అసురులను చంపిన ప్రతిసారీ శుక్రుడు మృతసంజీవనితో వారిని బతికించేవాడు — యుద్ధం ఎప్పటికీ ముగియలేదు. అందుకే శివుడు నందిని పంపాడు; నంది శుక్రుణ్ణి పట్టుకుని శివుని దగ్గరికి తెచ్చాడు. శివుడు ఆయనను మింగేశాడు. గురువు లేకపోవడంతో అసురులను ఇక బతికించలేకపోయారు; అంధకుడు ఓడిపోయాడు. శివుడు విడిచేవరకు శుక్రుడు ఆయనను స్తుతిస్తూ లోపలే ఉన్నాడు — మళ్ళీ వీర్యరూపంలో బయటకు వచ్చాడు; మళ్ళీ శుక్రుడు అనే పేరు వచ్చింది."]
   ]],
   ["dyk", "⚪", "Śukra also means “bright” or “white.” That is why the bright white planet Venus carries his name.", "శుక్ర అంటే “ప్రకాశవంతమైన” లేదా “తెల్లని” అని కూడా అర్థం. అందుకే తెల్లగా ప్రకాశించే శుక్ర గ్రహానికి ఆయన పేరు."],
   ["src", "Mahābhārata, Śānti Parva (Mokṣadharma Parva) — chapter 278 in the Critical Edition (289 in many printed editions). Śiva Purāṇa, Rudra Saṃhitā, Yuddha Khaṇḍa (the Andhaka war).", "మహాభారతం, శాంతిపర్వం (మోక్షధర్మ పర్వం) — విమర్శనాత్మక ప్రతి 278వ అధ్యాయం (చాలా ముద్రిత ప్రతులలో 289). శివ పురాణం, రుద్ర సంహిత, యుద్ధ ఖండం (అంధకాసుర యుద్ధం)."]
  ]
 ],
 remember: [
  ["Uśanā robbed {kubera|Kubera} by yoga; Śiva swallowed him.", "ఉశనుడు యోగబలంతో {kubera|కుబేరుని} దోచుకున్నాడు; శివుడు ఆయనను మింగేశాడు."],
  ["He came out of Śiva's body as his seed — śukra — and so got his name.", "శివుని శరీరం నుండి వీర్యంగా — శుక్రంగా — బయటకు వచ్చాడు; అలా ఆ పేరు వచ్చింది."],
  ["{parvati|Pārvatī} saved him, calling him her son.", "{parvati|పార్వతీదేవి} అతన్ని తన కుమారుడని చెప్పి కాపాడింది."]
 ],
 think: ["Uśanā escaped Śiva's trident by clinging to its very tip. Sometimes the safest place is closest to the danger. Can you think of an example?", "ఉశనుడు త్రిశూలపు కొనకే అతుక్కుని దాని నుండి తప్పించుకున్నాడు. కొన్నిసార్లు ప్రమాదానికి అతి దగ్గర ఉన్న చోటే సురక్షితమైనది. ఏదైనా ఉదాహరణ ఆలోచించగలరా?"]
},
{
 id: "sk-4", sage: "shukracharya", n: 4, order: 304, date: "2026-10-17",
 title: "Kaca and Devayānī", titleTe: "కచ దేవయాని",
 src: "Mahābhārata, Ādi Parva",
 who: ["kaca", "devayani", "brihaspati", "vrishaparva"],
 pages: [
  [
   ["p", "Now the war was hopeless for the gods. Every asura they killed, Śukra brought back to life. The devas met in despair and came up with a plan. They went to {kaca|Kaca}, the young son of Bṛhaspati. “Go to Śukra and become his student. He will not refuse a brāhmaṇa boy who asks to learn. Serve him, win his favour — and learn the Mṛtasañjīvanī. His daughter {devayani|Devayānī} is very dear to him. If you please her, you will please him.”", "ఇప్పుడు దేవతలకు యుద్ధం నిరాశాజనకంగా మారింది. వారు చంపిన ప్రతి అసురుణ్ణీ శుక్రుడు బతికించేవాడు. దేవతలు నిరాశతో సమావేశమై ఒక ఉపాయం ఆలోచించారు. బృహస్పతి యువ కుమారుడు {kaca|కచుని} దగ్గరికి వెళ్ళారు. “శుక్రుని దగ్గరికి వెళ్ళి శిష్యుడివి కా. నేర్చుకోవాలని అడిగే బ్రాహ్మణ బాలుణ్ణి ఆయన కాదనడు. సేవ చేసి ఆయన అనుగ్రహం పొంది — మృతసంజీవని నేర్చుకో. ఆయన కుమార్తె {devayani|దేవయాని} ఆయనకు ప్రాణం. ఆమెను సంతోషపెడితే ఆయనను సంతోషపెట్టినట్టే.”"],
   ["p", "Kaca went to Śukra's home in the asura city and said honestly: “I am Kaca, grandson of Aṅgiras and son of Bṛhaspati. Accept me as your student. I will keep the vow of brahmacarya under you for a thousand years.” Śukra knew exactly who he was. But a true teacher does not turn away a sincere student. “Welcome, Kaca. I accept you — and in doing so, I honour Bṛhaspati too.”", "కచుడు అసుర నగరంలోని శుక్రుని ఇంటికి వెళ్ళి నిజాయితీగా చెప్పాడు: “నేను కచుణ్ణి, అంగిరసుని మనవణ్ణి, బృహస్పతి కుమారుణ్ణి. నన్ను శిష్యునిగా స్వీకరించండి. మీ దగ్గర వెయ్యేళ్ళు బ్రహ్మచర్య వ్రతం పాటిస్తాను.” అతను ఎవరో శుక్రునికి బాగా తెలుసు. కానీ నిజమైన గురువు నిజాయితీ గల శిష్యుణ్ణి తిరస్కరించడు. “కచా, స్వాగతం. నిన్ను స్వీకరిస్తున్నాను — అలా బృహస్పతిని కూడా గౌరవిస్తున్నాను.”"],
   ["p", "Kaca served his guru faithfully, and he was kind to Devayānī — singing for her, dancing, bringing her flowers and fruits from the forest. She grew very fond of him.", "కచుడు గురువుకు విశ్వాసంగా సేవ చేశాడు; దేవయానితో ఆప్యాయంగా ఉండేవాడు — ఆమె కోసం పాడేవాడు, నాట్యం చేసేవాడు, అడవి నుండి పూలూ పండ్లూ తెచ్చేవాడు. ఆమెకు అతనంటే చాలా ఇష్టం ఏర్పడింది."]
  ],
  [
   ["h", "Killed Three Times", "మూడుసార్లు చంపబడినవాడు"],
   ["p", "The asuras understood why Bṛhaspati's son was there. One day, while Kaca was grazing his guru's cows in the forest, they caught him, killed him, cut him into pieces and fed him to wolves and jackals. In the evening the cows came home alone. Devayānī ran to her father: “Kaca has not come back. He must be dead. Without him I cannot live.” Śukra used the Mṛtasañjīvanī and called, “Come, Kaca!” — and Kaca burst out of the bodies of the wolves, alive and whole, and came home.", "బృహస్పతి కొడుకు అక్కడ ఎందుకున్నాడో అసురులు గ్రహించారు. ఒక రోజు కచుడు గురువు ఆవులను అడవిలో మేపుతుండగా పట్టుకుని, చంపి, ముక్కలు చేసి తోడేళ్ళకూ నక్కలకూ వేశారు. సాయంత్రం ఆవులు ఒంటరిగా ఇంటికి వచ్చాయి. దేవయాని తండ్రి దగ్గరికి పరుగెత్తింది: “కచుడు తిరిగి రాలేదు. చనిపోయి ఉంటాడు. అతను లేకుండా నేను బతకలేను.” శుక్రుడు మృతసంజీవని ప్రయోగించి, “కచా, రా!” అని పిలిచాడు — కచుడు తోడేళ్ళ శరీరాలను చీల్చుకుని, సజీవంగా, సంపూర్ణంగా బయటకు వచ్చి ఇంటికి వచ్చాడు."],
   ["p", "The second time, the asuras caught him picking flowers, killed him, ground him to a paste and mixed it into the sea. Again Devayānī wept; again Śukra called him back to life.", "రెండవసారి పూలు కోస్తుండగా పట్టుకుని, చంపి, ముద్దగా నూరి సముద్రంలో కలిపేశారు. మళ్ళీ దేవయాని ఏడ్చింది; మళ్ళీ శుక్రుడు అతన్ని బతికించాడు."],
   ["p", "The third time, the asuras were cleverer. They killed Kaca, burned his body to ash, mixed the ash into wine — and served it to Śukra himself, who drank it. Now when Devayānī cried for Kaca, Śukra called him — and Kaca's voice answered from inside Śukra's own belly. “Here I am, master. I am inside you.”", "మూడవసారి అసురులు మరింత తెలివిగా ప్రవర్తించారు. కచుణ్ణి చంపి, శరీరాన్ని కాల్చి బూడిద చేసి, ఆ బూడిదను మద్యంలో కలిపి — స్వయంగా శుక్రునికే ఇచ్చారు; ఆయన తాగేశాడు. ఇప్పుడు దేవయాని కచుని కోసం ఏడవగా శుక్రుడు అతన్ని పిలిచాడు — శుక్రుని కడుపులో నుండే కచుని గొంతు జవాబిచ్చింది. “గురువుగారూ, ఇక్కడే ఉన్నాను. మీ లోపల ఉన్నాను.”"]
  ],
  [
   ["p", "Now Śukra was trapped. If he brought Kaca out, his own belly would burst and he would die. If he did not, Kaca would stay dead and Devayānī would die of grief. “Father,” said Devayānī, “if either of you dies, I will not live.”", "ఇప్పుడు శుక్రుడు ఇరుక్కుపోయాడు. కచుణ్ణి బయటకు తెస్తే తన కడుపు చీలి తానే చనిపోతాడు. తేకపోతే కచుడు చనిపోయే ఉంటాడు; దేవయాని దుఃఖంతో చనిపోతుంది. “నాన్నా,” అంది దేవయాని, “మీ ఇద్దరిలో ఎవరు చనిపోయినా నేను బతకను.”"],
   ["p", "So Śukra did the only thing possible. He taught the Mṛtasañjīvanī to Kaca, right there inside his own body. Then he called him out. Kaca came out, tearing his guru's body open — and Śukra fell dead. At once Kaca used the mantra he had just learned and brought his guru back to life. He bowed at Śukra's feet. “You gave me life twice — once as my teacher, once from your own body. You are my father and my mother.”", "అందుకే శుక్రుడు సాధ్యమైన ఒకే ఒక్క పని చేశాడు. తన శరీరం లోపలే కచునికి మృతసంజీవని ఉపదేశించాడు. తర్వాత బయటకు రమ్మని పిలిచాడు. గురువు శరీరాన్ని చీల్చుకుంటూ కచుడు బయటకు వచ్చాడు — శుక్రుడు చనిపోయి పడిపోయాడు. వెంటనే కచుడు అప్పుడే నేర్చుకున్న మంత్రంతో గురువును బతికించాడు. శుక్రుని పాదాలపై పడ్డాడు. “మీరు నాకు రెండుసార్లు ప్రాణం ఇచ్చారు — ఒకసారి గురువుగా, ఒకసారి మీ శరీరం నుండి. మీరే నా తండ్రి, నా తల్లి.”"],
   ["p", "Śukra rose, furious — not at Kaca, but at what had happened. He declared: “From today, any brāhmaṇa who drinks wine out of foolishness falls from dharma and is a sinner in this world and the next.” It is said that this is how drinking came to be forbidden to brāhmaṇas.", "శుక్రుడు కోపంగా లేచాడు — కచుని మీద కాదు, జరిగినదాని మీద. ఇలా ప్రకటించాడు: “ఈ రోజు నుండి మూర్ఖత్వంతో మద్యం తాగే ఏ బ్రాహ్మణుడైనా ధర్మభ్రష్టుడు; ఇహపరలోకాలలో పాపి.” బ్రాహ్మణులకు మద్యపానం నిషిద్ధం కావడానికి ఇదే కారణమని చెబుతారు."]
  ],
  [
   ["h", "Two Curses", "రెండు శాపాలు"],
   ["p", "At the end of a thousand years, Kaca's vow was complete, and he prepared to go home. Devayānī stopped him. “Kaca, I have loved you all these years. Marry me.” Kaca answered gently: “Devayānī, you are my guru's daughter. And I have lived inside your father's body and been born again from it — that makes you my sister. I honour you as I honour him. I cannot marry you.”", "వెయ్యేళ్ళు పూర్తయి కచుని వ్రతం ముగిసింది; ఇంటికి వెళ్ళడానికి సిద్ధమయ్యాడు. దేవయాని అతన్ని ఆపింది. “కచా, ఇన్నేళ్ళూ నిన్ను ప్రేమించాను. నన్ను పెళ్ళి చేసుకో.” కచుడు మృదువుగా జవాబిచ్చాడు: “దేవయానీ, నువ్వు నా గురువు కూతురివి. నేను మీ నాన్న శరీరంలో ఉండి, దాని నుండి మళ్ళీ పుట్టాను — అంటే నువ్వు నా సోదరివి. ఆయనను గౌరవించినట్టే నిన్ను గౌరవిస్తాను. నిన్ను పెళ్ళి చేసుకోలేను.”"],
   ["p", "Devayānī was heartbroken, and her grief turned to anger. “Then the knowledge you came here for will be useless to you! You will never be able to use it yourself.” Kaca answered: “You curse me out of desire, not for any fault of mine. Very well. I cannot use it — but I can teach it, and those I teach will use it. And I say this: no son of a sage will ever marry you.” Then he went back to heaven, and taught the devas the Mṛtasañjīvanī.", "దేవయాని గుండె పగిలింది; ఆమె దుఃఖం కోపంగా మారింది. “అయితే నువ్వు దేని కోసం వచ్చావో ఆ విద్య నీకు నిష్ఫలం అవుతుంది! దాన్ని నువ్వు ఎప్పటికీ ప్రయోగించలేవు.” కచుడు జవాబిచ్చాడు: “నా ఏ తప్పూ లేకుండా కోరిక వల్ల నన్ను శపిస్తున్నావు. సరే. నేను ప్రయోగించలేను — కానీ బోధించగలను; నేను బోధించినవారు ప్రయోగిస్తారు. ఇది కూడా చెబుతున్నాను: ఏ ముని కుమారుడూ నిన్ను పెళ్ళి చేసుకోడు.” తర్వాత స్వర్గానికి వెళ్ళి దేవతలకు మృతసంజీవని నేర్పాడు."],
   ["dyk", "🎭", "Kaca and Devayānī is one of the best-loved love stories in Telugu — told in Nannaya's Telugu Mahābhāratam and in many films and plays as “Kaca-Devayāni.”", "కచ దేవయానుల కథ తెలుగులో అత్యంత ప్రియమైన ప్రేమకథలలో ఒకటి — నన్నయ ఆంధ్ర మహాభారతంలోనూ, ‘కచ దేవయాని’ పేరుతో ఎన్నో సినిమాలలో, నాటకాలలోనూ చెప్పబడింది."],
   ["src", "Mahābhārata, Ādi Parva (Sambhava Parva) — chapters 71–72 in the Critical Edition (76–77 in many printed editions). In Telugu: Nannaya's Āndhra Mahābhāratamu, Ādi Parva.", "మహాభారతం, ఆదిపర్వం (సంభవ పర్వం) — విమర్శనాత్మక ప్రతి 71–72 అధ్యాయాలు (చాలా ముద్రిత ప్రతులలో 76–77). తెలుగులో: నన్నయ ఆంధ్ర మహాభారతము, ఆదిపర్వం."]
  ]
 ],
 remember: [
  ["{kaca|Kaca}, Bṛhaspati's son, became Śukra's student to learn the Mṛtasañjīvanī.", "బృహస్పతి కుమారుడు {kaca|కచుడు} మృతసంజీవని నేర్చుకోవడానికి శుక్రుని శిష్యుడయ్యాడు."],
  ["The asuras killed him three times; the third time Śukra drank his ashes and had to teach him the mantra from inside.", "అసురులు అతన్ని మూడుసార్లు చంపారు; మూడవసారి శుక్రుడు అతని బూడిద తాగి, లోపలే మంత్రం నేర్పాల్సి వచ్చింది."],
  ["Kaca refused to marry {devayani|Devayānī}; they cursed each other.", "కచుడు {devayani|దేవయానిని} పెళ్ళి చేసుకోవడానికి నిరాకరించాడు; ఇద్దరూ ఒకరినొకరు శపించుకున్నారు."]
 ],
 think: ["Śukra knew Kaca was sent by his enemies, yet he taught him — even giving him the secret in the end. What does that tell you about what kind of teacher Śukra was?", "కచుణ్ణి శత్రువులు పంపారని శుక్రునికి తెలుసు; అయినా బోధించాడు — చివరికి రహస్యాన్నే ఇచ్చేశాడు. శుక్రుడు ఎలాంటి గురువో దీని వల్ల మనకు ఏమి తెలుస్తుంది?"]
},
{
 id: "sk-5", sage: "shukracharya", n: 5, order: 305, date: "2026-10-17",
 title: "Devayānī, Śarmiṣṭhā and Yayāti", titleTe: "దేవయాని, శర్మిష్ఠ, యయాతి",
 src: "Mahābhārata, Ādi Parva",
 who: ["devayani", "sharmishtha", "vrishaparva", "yayati", "puru"],
 pages: [
  [
   ["p", "One day {devayani|Devayānī} went to bathe in a forest pool with {sharmishtha|Śarmiṣṭhā}, the daughter of the asura king {vrishaparva|Vṛṣaparvan}, and their friends. They left their clothes on the bank. Indra, in the form of the wind, blew the clothes into a heap. When the girls came out of the water and dressed in a hurry, Śarmiṣṭhā put on Devayānī's garments by mistake.", "ఒక రోజు {devayani|దేవయాని} అసుర రాజు {vrishaparva|వృషపర్వుని} కుమార్తె {sharmishtha|శర్మిష్ఠతో}, స్నేహితురాళ్ళతో కలిసి అడవిలోని కొలనులో స్నానానికి వెళ్ళింది. బట్టలు ఒడ్డున పెట్టారు. గాలి రూపంలో వచ్చిన ఇంద్రుడు బట్టలన్నీ కలిపి ఒక కుప్పగా ఎగరేశాడు. అమ్మాయిలు నీటి నుండి బయటకు వచ్చి తొందరగా బట్టలు వేసుకుంటుండగా, శర్మిష్ఠ పొరపాటున దేవయాని బట్టలు వేసుకుంది."],
   ["p", "“How dare you, a pupil's daughter, wear the clothes of your guru's daughter!” cried Devayānī. Śarmiṣṭhā, a proud princess, shot back: “Your father sits below my father, praising him and begging from him day and night! You are the daughter of a beggar — I am the daughter of the king who gives.” In her anger, she pushed Devayānī into a dry well and walked away.", "“శిష్యుని కూతురివి — గురువు కూతురి బట్టలు వేసుకుంటావా!” అని అరిచింది దేవయాని. గర్విష్ఠి అయిన రాకుమారి శర్మిష్ఠ తిరిగి అంది: “మీ నాన్న రాత్రింబవళ్ళూ మా నాన్న కింద కూర్చుని ఆయనను పొగుడుతూ యాచిస్తాడు! నువ్వు యాచకుని కూతురివి — నేను దానం చేసే రాజు కూతురిని.” కోపంలో దేవయానిని ఒక పాడుబడిన బావిలోకి తోసేసి వెళ్ళిపోయింది."],
   ["p", "King {yayati|Yayāti}, hunting nearby and thirsty, came to the well looking for water and found a beautiful girl at the bottom. “Who are you?” “I am Devayānī, daughter of Śukrācārya. Take my right hand and pull me out.” He did, and went on his way.", "దగ్గరలో వేటాడుతూ దాహంతో ఉన్న {yayati|యయాతి} మహారాజు నీళ్ళ కోసం బావి దగ్గరికి వచ్చి అడుగున ఒక అందమైన అమ్మాయిని చూశాడు. “నువ్వెవరు?” “నేను శుక్రాచార్యుని కుమార్తె దేవయానిని. నా కుడిచేయి పట్టుకుని పైకి లాగండి.” ఆయన లాగి తన దారిన వెళ్ళిపోయాడు."]
  ],
  [
   ["h", "The Guru Threatens to Leave", "వెళ్ళిపోతానన్న గురువు"],
   ["p", "Devayānī would not go home. She sent word to her father, and Śukra came to find her weeping in the forest. He tried to calm her: “Daughter, we suffer the results of our own actions.” But hearing what Śarmiṣṭhā had said, his own pride was stung. He went straight to the king. “Vṛṣaparvan, your people have tried to kill my student Kaca again and again, and now your daughter has thrown my daughter into a well. I am leaving you.”", "దేవయాని ఇంటికి వెళ్ళలేదు. తండ్రికి కబురు పంపింది. శుక్రుడు వచ్చి అడవిలో ఏడుస్తున్న ఆమెను చూశాడు. “బిడ్డా, మన కర్మల ఫలాన్ని మనమే అనుభవిస్తాం,” అని శాంతపరచడానికి ప్రయత్నించాడు. కానీ శర్మిష్ఠ అన్న మాటలు విని ఆయన ఆత్మాభిమానం దెబ్బతింది. నేరుగా రాజు దగ్గరికి వెళ్ళాడు. “వృషపర్వా, నీ జనం నా శిష్యుడు కచుణ్ణి మళ్ళీ మళ్ళీ చంపడానికి ప్రయత్నించారు; ఇప్పుడు నీ కూతురు నా కూతుర్ని బావిలోకి తోసేసింది. నేను నిన్ను వదిలి వెళ్ళిపోతున్నాను.”"],
   ["p", "Vṛṣaparvan fell at his feet. Without Śukra, the asuras were finished. “Ask for anything! Only do not leave us.” “Then satisfy my daughter,” said Śukra. Devayānī made her demand: “Śarmiṣṭhā will be my servant, with a thousand of her maids, and she will follow me wherever my father gives me in marriage.”", "వృషపర్వుడు ఆయన పాదాలపై పడ్డాడు. శుక్రుడు లేకపోతే అసురుల పని అయిపోయినట్టే. “ఏది కావాలన్నా అడగండి! మమ్మల్ని వదిలి మాత్రం వెళ్ళకండి.” “అయితే నా కూతుర్ని సంతోషపెట్టు,” అన్నాడు శుక్రుడు. దేవయాని తన కోరిక చెప్పింది: “శర్మిష్ఠ వెయ్యి మంది దాసీలతో కలిసి నాకు దాసి కావాలి; మా నాన్న నన్ను ఎవరికిచ్చి పెళ్ళి చేస్తే అక్కడికి నా వెంట రావాలి.”"],
   ["p", "And the proud princess Śarmiṣṭhā, for the sake of her whole people, bowed her head and agreed. “If it keeps the guru with us, I will be her servant.”", "తన ప్రజలందరి కోసం గర్విష్ఠి రాకుమారి శర్మిష్ఠ తల వంచి ఒప్పుకుంది. “గురువు మాతో ఉంటారంటే, నేను ఆమెకు దాసినవుతాను.”"],
   ["dyk", "💎", "Many readers feel the true hero of this chapter is Śarmiṣṭhā — the princess who gave up everything for her people.", "ఈ అధ్యాయంలో నిజమైన నాయిక శర్మిష్ఠేనని చాలామంది పాఠకులు భావిస్తారు — తన ప్రజల కోసం సర్వస్వం వదులుకున్న రాకుమారి."]
  ],
  [
   ["h", "A Marriage, and a Broken Promise", "ఒక వివాహం, తప్పిన మాట"],
   ["p", "Later, Devayānī met Yayāti again in the forest. “You took my right hand,” she said. “A man who takes a girl's hand is her husband. Marry me.” Yayāti hesitated — a kṣatriya king marrying a brāhmaṇa's daughter was against custom, and he feared Śukra. But Śukra himself gave her to him, and said: “Take her as your queen, and honour Śarmiṣṭhā as well — but never invite Śarmiṣṭhā to your bed.”", "తర్వాత దేవయాని అడవిలో యయాతిని మళ్ళీ కలిసింది. “మీరు నా కుడిచేయి పట్టుకున్నారు,” అంది. “అమ్మాయి చేయి పట్టుకున్నవాడే ఆమె భర్త. నన్ను పెళ్ళి చేసుకోండి.” యయాతి సంకోచించాడు — క్షత్రియ రాజు బ్రాహ్మణ కన్యను పెళ్ళాడడం ఆచారానికి విరుద్ధం; శుక్రుడంటే భయం కూడా. కానీ శుక్రుడే ఆమెను ఆయనకు ఇచ్చి ఇలా అన్నాడు: “ఈమెను నీ రాణిగా స్వీకరించు; శర్మిష్ఠను కూడా గౌరవించు — కానీ శర్మిష్ఠను ఎప్పుడూ నీ శయ్యకు పిలవకు.”"],
   ["p", "Devayānī bore Yayāti two sons, Yadu and Turvasu. But years later Śarmiṣṭhā, now living in the palace grounds as a servant, came to the king and asked for a child. Yayāti could not refuse her, and he broke Śukra's command in secret. Śarmiṣṭhā bore him three sons: Druhyu, Anu and {puru|Puru}.", "దేవయాని యయాతికి యదువు, తుర్వసుడు అనే ఇద్దరు కుమారులను కన్నది. కానీ ఏళ్ళ తర్వాత రాజభవన ప్రాంగణంలో దాసిగా ఉంటున్న శర్మిష్ఠ రాజు దగ్గరికి వచ్చి సంతానం కోరింది. యయాతి ఆమెను కాదనలేక రహస్యంగా శుక్రుని ఆజ్ఞను ఉల్లంఘించాడు. శర్మిష్ఠ ఆయనకు ద్రుహ్యుడు, అనువు, {puru|పూరుడు} అనే ముగ్గురు కుమారులను కన్నది."],
   ["p", "One day Devayānī saw three bright little boys playing in the garden and asked whose they were. They pointed at the king. Devayānī, humiliated, left the palace and went straight to her father. Śukra's anger fell on Yayāti: “You broke my command. Let old age come upon you now, in your youth!” And Yayāti at once became a feeble old man.", "ఒక రోజు దేవయాని తోటలో ఆడుకుంటున్న ముగ్గురు చురుకైన పిల్లలను చూసి వారెవరని అడిగింది. వారు రాజు వైపు చూపించారు. అవమానంతో దేవయాని రాజభవనం వదిలి నేరుగా తండ్రి దగ్గరికి వెళ్ళింది. శుక్రుని కోపం యయాతి మీద పడింది: “నా ఆజ్ఞను ఉల్లంఘించావు. యవ్వనంలోనే నీకు ముసలితనం రావాలి!” యయాతి వెంటనే బలహీనుడైన వృద్ధుడయ్యాడు."]
  ],
  [
   ["h", "Puru's Gift", "పూరుని దానం"],
   ["p", "Yayāti begged for mercy. Śukra could not take back the curse, but he softened it: “If one of your sons will take your old age and give you his youth, you may exchange.” Yayāti asked his sons one by one. Yadu refused. Turvasu refused. Druhyu and Anu refused. Only the youngest, Puru, said, “Father, I will take your old age gladly.”", "యయాతి దయ కోసం వేడుకున్నాడు. శుక్రుడు శాపాన్ని వెనక్కి తీసుకోలేడు; కానీ సడలించాడు: “నీ కుమారులలో ఎవరైనా నీ ముసలితనం తీసుకుని తన యవ్వనం ఇస్తే, మార్చుకోవచ్చు.” యయాతి కొడుకులను ఒక్కొక్కరిగా అడిగాడు. యదువు కాదన్నాడు. తుర్వసుడు కాదన్నాడు. ద్రుహ్యుడూ అనువూ కాదన్నారు. చిన్నవాడైన పూరుడు ఒక్కడే, “నాన్నా, మీ ముసలితనాన్ని సంతోషంగా తీసుకుంటాను,” అన్నాడు."],
   ["p", "For a thousand years Yayāti enjoyed every pleasure with Puru's youth. At the end he gave the youth back to Puru and made him king over his elder brothers, saying words that have been repeated ever since:", "పూరుని యవ్వనంతో యయాతి వెయ్యేళ్ళు అన్ని సుఖాలూ అనుభవించాడు. చివరికి యవ్వనాన్ని పూరునికి తిరిగి ఇచ్చి, అన్నల కంటే అతన్నే రాజును చేస్తూ, అప్పటి నుండి మళ్ళీ మళ్ళీ చెప్పబడే మాటలు అన్నాడు:"],
   ["sloka", ["న జాతు కామః కామానాముపభోగేన శామ్యతి ।", "హవిషా కృష్ణవర్త్మేవ భూయ ఏవాభివర్ధతే ॥"], ["na jātu kāmaḥ kāmānām upabhogena śāmyati |", "haviṣā kṛṣṇavartmeva bhūya evābhivardhate ||"], "“Desire is never satisfied by enjoying what is desired. Like fire fed with ghee, it only grows stronger.”", "“కోరికలు అనుభవించడం వల్ల కోరిక ఎప్పుడూ తీరదు. నెయ్యి పోసిన అగ్నిలా, అది ఇంకా పెరుగుతుంది.”"],
   ["dyk", "🌳", "From Puru came the Pauravas — Bharata, Kuru, and at last the Kauravas and Pāṇḍavas. From Devayānī's son Yadu came the Yādavas, and Kṛṣṇa. And the five names — Yadu, Turvasu, Druhyu, Anu, Puru — are the same five peoples who fought King Sudās in the Ṛgveda's Battle of the Ten Kings.", "పూరుని నుండి పౌరవులు వచ్చారు — భరతుడు, కురువు, చివరికి కౌరవ పాండవులు. దేవయాని కుమారుడు యదువు నుండి యాదవులు — శ్రీకృష్ణుడు. ఈ ఐదు పేర్లు — యదు, తుర్వసు, ద్రుహ్యు, అను, పూరు — ఋగ్వేదపు దశరాజ యుద్ధంలో సుదాసునితో పోరాడిన అవే ఐదు జాతులు."],
   ["sglink", "Read about the Battle of the Ten Kings in Vasiṣṭha's life", "వసిష్ఠుని జీవితంలో దశరాజ యుద్ధం గురించి చదవండి", "va-3"],
   ["src", "Mahābhārata, Ādi Parva (Sambhava Parva) — chapters 73–80 in the Critical Edition (78–85 in many printed editions). The verse on desire is Yayāti's, in the Ādi Parva; it is also found in the Bhāgavata Purāṇa (9.19.14) and the Manusmṛti (2.94).", "మహాభారతం, ఆదిపర్వం (సంభవ పర్వం) — విమర్శనాత్మక ప్రతి 73–80 అధ్యాయాలు (చాలా ముద్రిత ప్రతులలో 78–85). కోరిక గురించిన శ్లోకం ఆదిపర్వంలో యయాతి చెప్పినది; భాగవతం (9.19.14), మనుస్మృతి (2.94) లలో కూడా ఉంది."]
  ]
 ],
 remember: [
  ["{sharmishtha|Śarmiṣṭhā} pushed {devayani|Devayānī} into a well; Śukra threatened to leave the asuras, and Śarmiṣṭhā became Devayānī's servant.", "{sharmishtha|శర్మిష్ఠ} {devayani|దేవయానిని} బావిలోకి తోసింది; శుక్రుడు అసురులను వదిలి వెళ్తానన్నాడు; శర్మిష్ఠ దేవయానికి దాసి అయింది."],
  ["{yayati|Yayāti} married Devayānī but secretly had sons with Śarmiṣṭhā; Śukra cursed him with old age.", "{yayati|యయాతి} దేవయానిని పెళ్ళాడి, రహస్యంగా శర్మిష్ఠతో సంతానం పొందాడు; శుక్రుడు ముసలితనంతో శపించాడు."],
  ["Only {puru|Puru} gave his youth to his father — ancestor of the Pāṇḍavas.", "తండ్రికి తన యవ్వనం ఇచ్చింది {puru|పూరుడు} ఒక్కడే — పాండవుల పూర్వీకుడు."]
 ],
 think: ["Yayāti had a thousand years of pleasure and still was not satisfied. What do you think would truly have satisfied him?", "యయాతి వెయ్యేళ్ళు సుఖాలు అనుభవించినా తృప్తి కలగలేదు. ఆయనకు నిజంగా ఏది తృప్తి కలిగించి ఉండేదని మీరనుకుంటున్నారు?"]
},
{
 id: "sk-6", sage: "shukracharya", n: 6, order: 306, date: "2026-10-17",
 title: "Arajā and the Daṇḍaka Forest", titleTe: "అరజ, దండకారణ్యం",
 src: "Rāmāyaṇa, Uttara Kāṇḍa",
 who: ["danda", "araja", "agastya", "rama"],
 pages: [
  [
   ["p", "When Rāma was living in exile, he spent years in a great, wild, lonely forest in central India — the Daṇḍakāraṇya. Long afterwards, as king, Rāma asked the sage {agastya|Agastya}: “Why is that forest so empty and wild? Who lived there before?” Agastya told him a story about Śukrācārya. This chapter tells of a crime against a young woman. It is told here plainly but without detail, because it is part of how the forest came to be.", "వనవాస కాలంలో రాముడు మధ్య భారతదేశంలోని ఒక మహా అరణ్యంలో — దండకారణ్యంలో — ఏళ్ళ తరబడి గడిపాడు. చాలా కాలం తర్వాత రాజుగా ఉన్నప్పుడు రాముడు {agastya|అగస్త్య} మహర్షిని అడిగాడు: “ఆ అడవి అంత నిర్జనంగా, అంత భయంకరంగా ఎందుకుంది? అంతకుముందు అక్కడ ఎవరు ఉండేవారు?” అగస్త్యుడు శుక్రాచార్యుని గురించి ఒక కథ చెప్పాడు. ఈ అధ్యాయం ఒక యువతికి జరిగిన అన్యాయం గురించి చెబుతుంది. ఆ అరణ్యం ఎలా ఏర్పడిందో దానిలో భాగం కాబట్టి, వివరాలు లేకుండా సూటిగా ఇక్కడ చెబుతున్నాం."],
   ["p", "Ikṣvāku, the first king of the Sun dynasty, had a hundred sons. The youngest was foolish and undisciplined, and his father, knowing he would be punished (daṇḍa) by fate one day, named him {danda|Daṇḍa}. Ikṣvāku gave him a kingdom between the Vindhya and Śaivala mountains, with a beautiful capital called Madhumanta. Śukrācārya, the Bhārgava, became his priest.", "సూర్యవంశపు మొదటి రాజు ఇక్ష్వాకునికి వంద మంది కుమారులు. చిన్నవాడు మూర్ఖుడు, క్రమశిక్షణ లేనివాడు; ఏదో ఒక రోజు విధి చేత దండన పొందుతాడని తెలిసి తండ్రి అతనికి {danda|దండుడు} అని పేరు పెట్టాడు. ఇక్ష్వాకుడు అతనికి వింధ్య, శైవల పర్వతాల మధ్య ఒక రాజ్యాన్ని, మధుమంతం అనే అందమైన రాజధానిని ఇచ్చాడు. భార్గవుడైన శుక్రాచార్యుడు అతని పురోహితుడయ్యాడు."]
  ],
  [
   ["p", "One spring day Daṇḍa came to Śukra's āśrama and saw the sage's daughter, {araja|Arajā}, walking alone in the forest. He was overcome by desire and approached her. Arajā said firmly: “I am the daughter of your own guru, Śukra. I am like a sister to you. If you want me, go to my father and ask him properly. If you do anything against my will, his anger will burn you.”", "ఒక వసంత దినాన దండుడు శుక్రుని ఆశ్రమానికి వచ్చి, అడవిలో ఒంటరిగా నడుస్తున్న ముని కుమార్తె {araja|అరజను} చూశాడు. కామంతో ఆమెను సమీపించాడు. అరజ దృఢంగా అంది: “నేను నీ సొంత గురువు శుక్రుని కూతురిని. నీకు సోదరి లాంటిదాన్ని. నన్ను కోరుకుంటే మా నాన్న దగ్గరికి వెళ్ళి పద్ధతిగా అడుగు. నా ఇష్టానికి వ్యతిరేకంగా ఏమైనా చేస్తే ఆయన కోపం నిన్ను భస్మం చేస్తుంది.”"],
   ["p", "Daṇḍa would not listen. He seized her and assaulted her against her will, and then rode away to his city. Arajā, shaking and in tears, waited near the āśrama for her father to return.", "దండుడు వినలేదు. ఆమెను బలవంతంగా పట్టుకుని, ఆమె ఇష్టానికి వ్యతిరేకంగా అత్యాచారం చేసి, తన నగరానికి వెళ్ళిపోయాడు. అరజ వణుకుతూ, కన్నీళ్ళతో తండ్రి కోసం ఆశ్రమం దగ్గర ఎదురుచూసింది."]
  ],
  [
   ["p", "When Śukra came back and saw his daughter's state and heard what had happened, his anger was like fire at the end of the world. He cursed: “This wicked king has done a terrible wrong. Within seven days, his kingdom will be destroyed — his army, his city, everything — by a great rain of dust sent by Indra. And let this whole land, a hundred yojanas around, become a wilderness where no one lives.”", "శుక్రుడు తిరిగి వచ్చి కూతురి స్థితి చూసి జరిగింది విన్నాడు; ఆయన కోపం ప్రళయాగ్నిలా మండింది. శపించాడు: “ఈ దుష్ట రాజు ఘోరమైన అన్యాయం చేశాడు. ఏడు రోజుల్లో ఇంద్రుడు కురిపించే మహా ధూళి వర్షంలో అతని రాజ్యం — సైన్యం, నగరం, సర్వం — నాశనమవుతుంది. చుట్టూ వంద యోజనాల ఈ దేశమంతా ఎవరూ నివసించని అరణ్యంగా మారుగాక.”"],
   ["p", "He told the people of the āśrama to leave the land at once. To Arajā he said gently: “Stay here, my daughter, by this lake, and live in peace and tapas. No harm will touch you. Every creature that comes here at night to drink at this lake will be safe.” Then Śukra left. Within seven days, Daṇḍa and his kingdom were buried under the rain of dust.", "ఆశ్రమవాసులను వెంటనే ఆ దేశం వదిలి వెళ్ళమని చెప్పాడు. అరజతో మృదువుగా అన్నాడు: “బిడ్డా, ఇక్కడే ఈ సరస్సు దగ్గర శాంతిగా, తపస్సుతో ఉండు. నీకు ఏ హానీ జరగదు. రాత్రి ఈ సరస్సులో నీళ్ళు తాగడానికి వచ్చే ప్రతి ప్రాణీ సురక్షితంగా ఉంటుంది.” తర్వాత శుక్రుడు వెళ్ళిపోయాడు. ఏడు రోజుల్లో దండుడూ అతని రాజ్యమూ ధూళి వర్షంలో సమాధి అయ్యాయి."],
   ["p", "That empty land became the Daṇḍakāraṇya, “the forest of Daṇḍa.” And it was there, ages later, that Rāma, Sītā and Lakṣmaṇa lived among the sages — and where Rāma's own great story of protecting the innocent unfolded.", "ఆ నిర్జన దేశమే దండకారణ్యం — “దండుని అరణ్యం” — అయింది. యుగాల తర్వాత అక్కడే రామ సీతా లక్ష్మణులు మునుల మధ్య నివసించారు — అమాయకులను కాపాడిన రాముని మహా కథ అక్కడే జరిగింది."],
   ["dyk", "🗺️", "The Daṇḍakāraṇya region is still called by that name — the forests of Chhattisgarh, Odisha, Telangana and Andhra Pradesh around the Godāvarī. Bhadrācalam, where Rāma is said to have lived in exile, lies in it.", "దండకారణ్య ప్రాంతాన్ని ఇప్పటికీ ఆ పేరుతోనే పిలుస్తారు — గోదావరి చుట్టూ ఉన్న ఛత్తీస్‌గఢ్, ఒడిశా, తెలంగాణ, ఆంధ్రప్రదేశ్ అడవులు. రాముడు వనవాసంలో నివసించాడని చెప్పే భద్రాచలం దానిలోనే ఉంది."],
   ["src", "Vālmīki Rāmāyaṇa, Uttara Kāṇḍa, sargas 79–81, told by Agastya to Rāma.", "వాల్మీకి రామాయణం, ఉత్తరకాండ, 79–81 సర్గలు — అగస్త్యుడు రామునికి చెప్పిన కథ."]
  ]
 ],
 remember: [
  ["King {danda|Daṇḍa}, Ikṣvāku's youngest son, assaulted Śukra's daughter {araja|Arajā}.", "ఇక్ష్వాకుని చిన్న కుమారుడు {danda|దండుడు} శుక్రుని కుమార్తె {araja|అరజపై} అత్యాచారం చేశాడు."],
  ["Śukra cursed his kingdom to be buried by a rain of dust within seven days.", "ఏడు రోజుల్లో అతని రాజ్యం ధూళి వర్షంలో సమాధి కావాలని శుక్రుడు శపించాడు."],
  ["The land became the Daṇḍaka forest, where Rāma later lived in exile.", "ఆ దేశం దండకారణ్యమైంది; తర్వాత రాముడు అక్కడ వనవాసం చేశాడు."]
 ],
 think: ["Arajā told Daṇḍa “no” clearly, and he ignored her. What does this story teach about respecting another person's no?", "అరజ దండునికి స్పష్టంగా “వద్దు” అని చెప్పింది; అతను పట్టించుకోలేదు. ఇతరుల “వద్దు”ను గౌరవించడం గురించి ఈ కథ ఏమి నేర్పుతుంది?"]
},
{
 id: "sk-7", sage: "shukracharya", n: 7, order: 307, date: "2026-10-17",
 title: "Bali and the Dwarf", titleTe: "బలి, వామనుడు",
 src: "Bhāgavata Purāṇa, Book 8",
 who: ["bali", "vamana", "aditi", "prahlada", "indra"],
 pages: [
  [
   ["p", "{bali|Bali}, the grandson of Prahlāda, was the greatest of the asura kings — generous, brave and truthful. Once, in a war, Indra struck him down with the thunderbolt, and Bali lay dead on the battlefield. His people carried his body to their guru. Śukra used the Mṛtasañjīvanī and brought him back to life.", "ప్రహ్లాదుని మనవడు {bali|బలి} అసుర రాజులందరిలోనూ గొప్పవాడు — దానశీలి, ధైర్యవంతుడు, సత్యవంతుడు. ఒకసారి యుద్ధంలో ఇంద్రుడు వజ్రాయుధంతో అతన్ని కూల్చాడు; బలి యుద్ధభూమిలో చనిపోయి పడి ఉన్నాడు. అతని ప్రజలు శరీరాన్ని గురువు దగ్గరికి తీసుకెళ్ళారు. శుక్రుడు మృతసంజీవనితో అతన్ని బతికించాడు."],
   ["p", "Bali served his guru with complete devotion, and the Bhārgava sages, led by Śukra, performed the great Viśvajit yajña for him. From the sacred fire rose a golden chariot with horses as swift as Indra's, a divine bow, two quivers that never emptied, and heavenly armour. Prahlāda gave him a garland of unfading flowers. With these, Bali marched on heaven, and Indra and the gods fled without a fight. Śukra then had Bali begin a hundred aśvamedha yajñas, to make his rule over the three worlds permanent.", "బలి సంపూర్ణ భక్తితో గురువుకు సేవ చేశాడు. శుక్రుని నాయకత్వంలో భార్గవ మునులు అతనికి విశ్వజిత్ మహాయజ్ఞం చేశారు. పవిత్రాగ్ని నుండి ఇంద్రుని గుర్రాలంత వేగమైన గుర్రాలున్న బంగారు రథం, దివ్య ధనుస్సు, ఎప్పటికీ ఖాళీ కాని రెండు అమ్ములపొదులు, దివ్య కవచం పైకి వచ్చాయి. ప్రహ్లాదుడు వాడని పూలమాల ఇచ్చాడు. వీటితో బలి స్వర్గం మీదికి దండెత్తాడు; యుద్ధం చేయకుండానే ఇంద్రుడూ దేవతలూ పారిపోయారు. తర్వాత ముల్లోకాల మీద తన పాలనను శాశ్వతం చేసుకోవడానికి శుక్రుడు బలి చేత నూరు అశ్వమేధ యాగాలు ప్రారంభింపజేశాడు."]
  ],
  [
   ["h", "A Little Brāhmaṇa Boy", "ఒక చిన్న బ్రాహ్మణ బాలుడు"],
   ["p", "{aditi|Aditi}, mother of the gods, grieved for her sons and prayed to Viṣṇu. Viṣṇu was born as her son — a tiny brāhmaṇa boy named {vamana|Vāmana}, carrying an umbrella and a water-pot. He came to Bali's yajña on the banks of the Narmadā. Bali welcomed him warmly, washed his feet, and said, “Ask me for anything — land, gold, cows, elephants, villages.”", "దేవతల తల్లి {aditi|అదితి} కుమారుల కోసం దుఃఖించి విష్ణువును ప్రార్థించింది. విష్ణువు ఆమె కుమారునిగా జన్మించాడు — గొడుగూ కమండలమూ పట్టుకున్న {vamana|వామనుడు} అనే చిన్న బ్రాహ్మణ బాలుడు. నర్మదా తీరంలో బలి యజ్ఞానికి వచ్చాడు. బలి ఆప్యాయంగా ఆహ్వానించి, ఆయన పాదాలు కడిగి, “భూమి, బంగారం, గోవులు, ఏనుగులు, గ్రామాలు — ఏది కావాలన్నా అడుగు,” అన్నాడు."],
   ["p", "Vāmana smiled. “I want only three steps of land, measured by my own feet.” Bali laughed. “Just three steps? Ask for more, little one — you are asking the lord of the three worlds!” “A person who is not satisfied with three steps,” said Vāmana, “will not be satisfied with a whole continent.”", "వామనుడు నవ్వాడు. “నా పాదాలతో కొలిచిన మూడడుగుల నేల మాత్రమే కావాలి.” బలి నవ్వాడు. “మూడడుగులేనా? ఇంకా అడుగు, చిన్నవాడా — ముల్లోకాధిపతిని అడుగుతున్నావు!” “మూడడుగులతో తృప్తి పడనివాడు ఒక ఖండమంతా ఇచ్చినా తృప్తి పడడు,” అన్నాడు వామనుడు."]
  ],
  [
   ["h", "The Guru's Warning", "గురువు హెచ్చరిక"],
   ["p", "But Śukra, sitting beside Bali, had seen through the disguise. He took his disciple aside. “Bali, listen to me. This is no boy. This is Viṣṇu himself, come to take back the three worlds for the gods. With one step he will cover the earth, with the second the heavens — and where will you put the third? Do not give it.”", "కానీ బలి పక్కన కూర్చున్న శుక్రుడు ఆ మారువేషాన్ని పసిగట్టాడు. శిష్యుణ్ణి పక్కకు పిలిచాడు. “బలీ, నా మాట విను. ఇతను బాలుడు కాదు. దేవతల కోసం ముల్లోకాలను తిరిగి తీసుకోవడానికి వచ్చిన సాక్షాత్తు విష్ణువు. ఒక్క అడుగుతో భూమిని, రెండవ అడుగుతో స్వర్గాన్ని ఆక్రమిస్తాడు — మూడవ అడుగు ఎక్కడ పెడతావు? ఇవ్వకు.”"],
   ["p", "“But I have already promised,” said Bali. Śukra replied with his famous teaching on when a promise may be broken: “A promise that destroys the one who makes it is not dharma. In jest, to win a bride, to save one's livelihood, to save a life, to protect cows and brāhmaṇas — in such cases a false word is not a sin. Take back your word.”", "“కానీ ఇప్పటికే మాట ఇచ్చేశాను,” అన్నాడు బలి. మాట ఎప్పుడు తప్పవచ్చో శుక్రుడు తన ప్రసిద్ధ బోధతో జవాబిచ్చాడు: “ఇచ్చినవాణ్ణే నాశనం చేసే మాట ధర్మం కాదు. హాస్యంలో, వివాహం కోసం, జీవనోపాధి కోసం, ప్రాణం కాపాడడానికి, గోవులనూ బ్రాహ్మణులనూ రక్షించడానికి — ఇలాంటి సందర్భాల్లో అసత్యం పాపం కాదు. నీ మాట వెనక్కి తీసుకో.”"],
   ["p", "Bali was silent for a moment. Then he said: “Guru, you are right that he is Viṣṇu. But that is all the more reason. I am Prahlāda's grandson. I will not lie to a brāhmaṇa who has come to me asking. If Viṣṇu himself stands before me with his hand held out, what greater fortune could a giver have?” Śukra's face darkened. “You disobey your guru, fool? Then you will lose all your wealth and power!” Bali bowed his head, accepted the curse, and turned to give the gift.", "బలి ఒక్క క్షణం మౌనంగా ఉన్నాడు. తర్వాత అన్నాడు: “గురువుగారూ, ఈయన విష్ణువేనని మీరు చెప్పింది నిజమే. అయితే ఇంకా ఎక్కువ కారణం. నేను ప్రహ్లాదుని మనవడిని. యాచించడానికి వచ్చిన బ్రాహ్మణునికి అబద్ధం చెప్పను. సాక్షాత్తు విష్ణువే చేయి చాచి నా ముందు నిలబడితే, దాతకు అంతకంటే గొప్ప భాగ్యం ఏముంటుంది?” శుక్రుని ముఖం నల్లబడింది. “మూర్ఖుడా, గురువు మాట కాదంటావా? అయితే నీ సంపదా శక్తీ అంతా కోల్పోతావు!” బలి తల వంచి శాపాన్ని స్వీకరించి, దానం ఇవ్వడానికి తిరిగాడు."],
   ["more", "The guru in the water-pot — a story loved in Telugu homes", "కమండలంలో గురువు — తెలుగు ఇళ్ళలో ప్రియమైన కథ", "From later tellings, not in the Bhāgavata itself", "తర్వాతి కథనాల నుండి; భాగవతంలో లేదు", [
     ["p", "To make a gift, the giver pours water from a spouted pot into the receiver's hand. Later tellings say that Śukra, desperate to stop the gift, made himself tiny and slipped into the spout of the pot to block the water. Vāmana smiled, took a blade of darbha grass and poked it into the spout to clear it — and it pierced one of Śukra's eyes. Śukra tumbled out, and the water flowed. That, the story says, is why Śukrācārya has only one eye.", "దానం చేసేటప్పుడు దాత కొమ్ము ఉన్న పాత్ర నుండి గ్రహీత చేతిలోకి నీళ్ళు పోస్తాడు. దానాన్ని ఎలాగైనా ఆపాలని శుక్రుడు చిన్న రూపం దాల్చి నీళ్ళు రాకుండా ఆ కలశం కొమ్ములో దూరాడని తర్వాతి కథనాలు చెబుతాయి. వామనుడు నవ్వి, ఒక దర్భపోచతో కొమ్మును శుభ్రం చేయడానికి పొడిచాడు — అది శుక్రుని ఒక కంటిలో గుచ్చుకుంది. శుక్రుడు బయటపడ్డాడు; నీళ్ళు ప్రవహించాయి. అందుకే శుక్రాచార్యునికి ఒక కన్ను మాత్రమే ఉందని ఆ కథ చెబుతుంది."]
   ]]
  ],
  [
   ["h", "Three Steps", "మూడడుగులు"],
   ["p", "The moment the water touched Vāmana's hand, the little boy began to grow — past the trees, past the clouds, past the sun and the stars — into Trivikrama, the One of Three Strides. With one step he covered the whole earth. With the second, all the heavens. “Where shall I put my third step, Bali?” Bali knelt and bowed his head. “Place it here, Lord, on my head.” Vāmana placed his foot on Bali's head and sent him down to Sutala, a beautiful world below the earth, more splendid than heaven — and Viṣṇu himself agreed to stand guard at Bali's door.", "నీళ్ళు వామనుని చేతిని తాకిన క్షణమే ఆ చిన్న బాలుడు పెరగడం మొదలుపెట్టాడు — చెట్లను దాటి, మేఘాలను దాటి, సూర్యనక్షత్రాలను దాటి — త్రివిక్రముడయ్యాడు. ఒక అడుగుతో భూమినంతా ఆక్రమించాడు. రెండవ అడుగుతో స్వర్గాలన్నిటినీ. “బలీ, మూడవ అడుగు ఎక్కడ పెట్టాలి?” బలి మోకరిల్లి తల వంచాడు. “ప్రభూ, ఇక్కడ — నా తల మీద పెట్టండి.” వామనుడు బలి తల మీద పాదం ఉంచి, స్వర్గం కంటే వైభవమైన సుతల లోకానికి పంపాడు — బలి ద్వారానికి స్వయంగా విష్ణువే కాపలాదారుగా ఉంటానని మాట ఇచ్చాడు."],
   ["p", "Then something beautiful happened. Viṣṇu turned to Śukra: “Śukra, Bali's yajña was left unfinished. Complete it, and make good whatever was missing.” Śukra, who had fought Viṣṇu all his life, bowed to him. “Lord, where you are present, nothing can be missing. Your name alone makes every rite complete.” And at Viṣṇu's word, the guru of the demons completed his disciple's yajña.", "అప్పుడు ఒక అందమైన విషయం జరిగింది. విష్ణువు శుక్రుని వైపు తిరిగాడు: “శుక్రా, బలి యజ్ఞం అసంపూర్ణంగా మిగిలిపోయింది. దాన్ని పూర్తి చేసి, లోపం ఏదైనా ఉంటే సరిదిద్దు.” జీవితమంతా విష్ణువుతో పోరాడిన శుక్రుడు ఆయనకు నమస్కరించాడు. “ప్రభూ, మీరున్న చోట లోపం ఉండదు. మీ నామమే ప్రతి కర్మనూ సంపూర్ణం చేస్తుంది.” విష్ణువు ఆజ్ఞతో రాక్షస గురువు తన శిష్యుని యజ్ఞాన్ని పూర్తి చేశాడు."],
   ["dyk", "🌾", "In Kerala, Onam celebrates Bali (Mahābali) returning once a year to visit his people. And Bali is one of the seven Cirañjīvīs, the immortals, along with Hanumān, Vibhīṣaṇa, Vyāsa, Aśvatthāmā, Kṛpa and Paraśurāma.", "కేరళలో ఓణం పండుగ బలి (మహాబలి) ఏడాదికి ఒకసారి తన ప్రజలను చూడడానికి తిరిగి రావడాన్ని జరుపుకుంటుంది. హనుమంతుడు, విభీషణుడు, వ్యాసుడు, అశ్వత్థామ, కృపుడు, పరశురాములతో పాటు బలి కూడా సప్త చిరంజీవులలో ఒకడు."],
   ["src", "Bhāgavata Purāṇa, Book 8, chapters 15–23 (Śukra's advice, 8.19; Śukra's curse, 8.20; Śukra completes the yajña, 8.23). The water-pot and the lost eye come from later tellings.", "భాగవత పురాణం, 8వ స్కంధం, 15–23 అధ్యాయాలు (శుక్రుని హితవు, 8.19; శుక్రుని శాపం, 8.20; శుక్రుడు యజ్ఞం పూర్తి చేయడం, 8.23). కమండలం, కన్ను కోల్పోవడం తర్వాతి కథనాల నుండి."]
  ]
 ],
 remember: [
  ["Śukra brought {bali|Bali} back to life and made him master of the three worlds.", "శుక్రుడు {bali|బలిని} బతికించి ముల్లోకాధిపతిని చేశాడు."],
  ["He recognized {vamana|Vāmana} as Viṣṇu and told Bali to take back his promise; Bali refused, and was cursed.", "{vamana|వామనుణ్ణి} విష్ణువుగా గుర్తించి మాట వెనక్కి తీసుకోమన్నాడు; బలి నిరాకరించి శాపం పొందాడు."],
  ["At the end, Śukra bowed to Viṣṇu and completed the yajña.", "చివరికి శుక్రుడు విష్ణువుకు నమస్కరించి యజ్ఞం పూర్తి చేశాడు."]
 ],
 think: ["Śukra gave Bali good practical advice; Bali chose his word over his kingdom. Who was right — the wise guru or the truthful king?", "శుక్రుడు బలికి ఆచరణాత్మకమైన మంచి సలహా ఇచ్చాడు; బలి రాజ్యం కంటే మాటనే ఎంచుకున్నాడు. ఎవరిది సరైనది — జ్ఞాని అయిన గురువుదా, సత్యవంతుడైన రాజుదా?"]
},
{
 id: "sk-8", sage: "shukracharya", n: 8, order: 308, date: "2026-10-17",
 title: "Teacher of Demons, Teacher of Kings", titleTe: "రాక్షస గురువు, రాజ గురువు",
 src: "Bhāgavata · Arthaśāstra · Bhagavad Gītā",
 who: ["prahlada", "krishna"],
 pages: [
  [
   ["p", "Śukra's influence reached far beyond the asuras. Even in the most famous asura household of all — Hiraṇyakaśipu's — it was Śukra's family that taught the children. When Śukra was away doing tapas, the king gave his son {prahlada|Prahlāda} to Śukra's two sons, Ṣaṇḍa and Amarka, to be educated in politics, warfare and the duties of a king.", "శుక్రుని ప్రభావం అసురులను దాటి ఎంతో దూరం వ్యాపించింది. అత్యంత ప్రసిద్ధమైన అసుర కుటుంబంలో కూడా — హిరణ్యకశిపుని ఇంట్లో — పిల్లలకు చదువు చెప్పింది శుక్రుని కుటుంబమే. శుక్రుడు తపస్సుకు దూరంగా ఉన్నప్పుడు రాజు తన కుమారుడు {prahlada|ప్రహ్లాదుణ్ణి} రాజనీతి, యుద్ధవిద్య, రాజధర్మాలు నేర్చుకోవడానికి శుక్రుని ఇద్దరు కుమారులు చండామార్కులకు (షండ, అమర్కులకు) అప్పగించాడు."],
   ["p", "But no matter what Ṣaṇḍa and Amarka taught, little Prahlāda kept talking about Viṣṇu. When Hiraṇyakaśipu asked his son what was the best thing he had learned, Prahlāda said: “To hear about Viṣṇu, to sing of him, to remember him, to serve him.” The furious father blamed the teachers: “What have you taught my son?” Poor Ṣaṇḍa and Amarka swore that they had never taught him any of it — it came from Prahlāda's own heart.", "చండామార్కులు ఏమి నేర్పినా బాల ప్రహ్లాదుడు విష్ణువు గురించే మాట్లాడేవాడు. నేర్చుకున్నదానిలో ఉత్తమమైనది ఏమిటని హిరణ్యకశిపుడు అడిగినప్పుడు ప్రహ్లాదుడు చెప్పాడు: “విష్ణువు కథలు వినడం, ఆయనను కీర్తించడం, స్మరించడం, సేవించడం.” కోపించిన తండ్రి గురువులను నిందించాడు: “నా కొడుక్కి ఏం నేర్పారు?” పాపం చండామార్కులు తాము అవేవీ నేర్పలేదని ప్రమాణం చేశారు — అదంతా ప్రహ్లాదుని హృదయం నుండే వచ్చింది."],
   ["dyk", "📖", "In Telugu, Potana's Bhāgavatam made Prahlāda's teachers famous as “Caṇḍāmarkulu,” and his school scenes are recited by heart in Telugu homes.", "తెలుగులో పోతన భాగవతం ప్రహ్లాదుని గురువులను “చండామార్కులు”గా ప్రసిద్ధి చేసింది; ఆయన బడి పద్యాలు తెలుగు ఇళ్ళలో కంఠస్థంగా వినిపిస్తాయి."]
  ],
  [
   ["h", "Father of Political Science", "రాజనీతి శాస్త్ర పితామహుడు"],
   ["p", "Śukra was not only a master of mantras. He was famous as the greatest teacher of nīti — statecraft, the art of ruling. The Mahābhārata quotes the teachings of Uśanas again and again when it speaks of how kings should rule, make war and keep peace. Even Bhīṣma, explaining rājadharma to Yudhiṣṭhira, cites Śukra as an authority.", "శుక్రుడు మంత్రాలలో మాత్రమే నిపుణుడు కాదు. నీతి — రాజ్యపాలన కళ — బోధించే గురువులలో అగ్రగణ్యునిగా ప్రసిద్ధుడు. రాజులు ఎలా పాలించాలి, యుద్ధం ఎలా చేయాలి, శాంతి ఎలా కాపాడాలి అని చెప్పేటప్పుడు మహాభారతం ఉశనుని బోధనలను మళ్ళీ మళ్ళీ ఉటంకిస్తుంది. ధర్మరాజుకు రాజధర్మం వివరిస్తున్న భీష్ముడు కూడా శుక్రుణ్ణి ప్రమాణంగా చూపిస్తాడు."],
   ["p", "Kauṭilya's Arthaśāstra, India's great ancient book on government, names the “school of Uśanas” as one of the old schools of political thought. It says the followers of Uśanas held that daṇḍanīti — the science of government and just punishment — is the one science that holds all the others together. A later work on statecraft, the Śukranīti, also carries his name.", "భారతదేశపు ప్రాచీన రాజనీతి గ్రంథమైన కౌటిల్యుని అర్థశాస్త్రం “ఔశనసుల” — ఉశనుని సంప్రదాయం — ను పాత రాజనీతి సంప్రదాయాలలో ఒకటిగా పేర్కొంటుంది. దండనీతి — పాలన, న్యాయమైన దండన శాస్త్రం — మిగతా శాస్త్రాలన్నిటినీ కలిపి నిలబెట్టే ఒకే శాస్త్రమని ఉశనుని అనుచరులు భావించేవారని అది చెబుతుంది. తర్వాతి కాలపు రాజనీతి గ్రంథం శుక్రనీతి కూడా ఆయన పేరునే కలిగి ఉంది."],
   ["dyk", "👁️", "A saying attributed to Śukra: “There is no syllable that is not a mantra, no root that is not a medicine, no person who is useless. What is rare is the one who knows how to use them.”", "శుక్రునిదిగా చెప్పే ఒక సూక్తి: “మంత్రం కాని అక్షరం లేదు, ఔషధం కాని వేరు లేదు, పనికిరాని మనిషి లేదు. వాటిని ఎలా ఉపయోగించాలో తెలిసినవాడే అరుదు.”"]
  ],
  [
   ["h", "“Among Poets, I Am Uśanā”", "“కవులలో ఉశనుణ్ణి నేను”"],
   ["p", "The highest honour of all came from {krishna|Kṛṣṇa}. In the Bhagavad Gītā, describing his own glories to Arjuna, Kṛṣṇa says that in everything great, he is the greatest: among mountains he is Meru, among rivers the Gaṅgā. And among seers and poets, he names — of all people — the guru of the demons:", "అత్యున్నత గౌరవం {krishna|శ్రీకృష్ణుని} నుండి వచ్చింది. భగవద్గీతలో అర్జునునికి తన విభూతులను వర్ణిస్తూ, గొప్పవాటన్నిటిలో తానే శ్రేష్ఠమైనవాడినని కృష్ణుడు చెబుతాడు: పర్వతాలలో మేరువు, నదులలో గంగ. మునులలో, కవులలో — అందరినీ వదిలి — రాక్షసుల గురువునే పేర్కొంటాడు:"],
   ["sloka", ["వృష్ణీనాం వాసుదేవోఽస్మి పాండవానాం ధనంజయః ।", "మునీనామప్యహం వ్యాసః కవీనాముశనా కవిః ॥"], ["vṛṣṇīnāṃ vāsudevo 'smi pāṇḍavānāṃ dhanañjayaḥ |", "munīnām apy ahaṃ vyāsaḥ kavīnām uśanā kaviḥ ||"], "“Among the Vṛṣṇis I am Vāsudeva; among the Pāṇḍavas, Arjuna. Among sages I am Vyāsa; among poets, the poet Uśanā.” (Bhagavad Gītā 10.37)", "“వృష్ణులలో వాసుదేవుణ్ణి, పాండవులలో అర్జునుణ్ణి. మునులలో వ్యాసుణ్ణి, కవులలో ఉశన కవిని నేను.” (భగవద్గీత 10.37)"],
   ["p", "Think of what this means. Śukra fought the gods all his life. He stood against Viṣṇu himself at Bali's yajña. And yet Kṛṣṇa — Viṣṇu — names him as one of his own glories. Greatness, the Gītā is saying, is greatness, whichever side it stands on.", "దీని అర్థం ఆలోచించండి. శుక్రుడు జీవితమంతా దేవతలతో పోరాడాడు. బలి యజ్ఞంలో సాక్షాత్తు విష్ణువుకే ఎదురు నిలిచాడు. అయినా కృష్ణుడు — విష్ణువు — ఆయనను తన విభూతులలో ఒకటిగా పేర్కొంటాడు. గొప్పతనం ఏ పక్షాన ఉన్నా గొప్పతనమే అని గీత చెబుతోంది."],
   ["src", "Bhāgavata Purāṇa 7.5 (Ṣaṇḍa and Amarka). Mahābhārata, Śānti Parva (Rājadharma). Kauṭilya's Arthaśāstra 1.2. Bhagavad Gītā 10.37. The saying on mantras and medicines is traditionally attributed to Śukra; the Śukranīti is a later work bearing his name.", "భాగవత పురాణం 7.5 (చండామార్కులు). మహాభారతం, శాంతిపర్వం (రాజధర్మం). కౌటిల్య అర్థశాస్త్రం 1.2. భగవద్గీత 10.37. మంత్రాలు, ఔషధాల సూక్తి సంప్రదాయంగా శుక్రునిదిగా చెప్పబడుతుంది; శుక్రనీతి ఆయన పేరుతో ఉన్న తర్వాతి కాలపు గ్రంథం."]
  ]
 ],
 remember: [
  ["Śukra's sons Ṣaṇḍa and Amarka were {prahlada|Prahlāda}'s teachers.", "శుక్రుని కుమారులు చండామార్కులు {prahlada|ప్రహ్లాదుని} గురువులు."],
  ["He was the great ancient teacher of statecraft, cited in the Mahābhārata and the Arthaśāstra.", "మహాభారతం, అర్థశాస్త్రం ఉటంకించే మహా ప్రాచీన రాజనీతి గురువు ఆయన."],
  ["In the Gītā, Kṛṣṇa says: “Among poets, I am Uśanā.”", "గీతలో కృష్ణుడు “కవులలో ఉశనుణ్ణి నేను” అంటాడు."]
 ],
 think: ["Kṛṣṇa praised a guru who spent his life opposing the gods. Can you respect someone's skill even when they are on the “other side”?", "జీవితమంతా దేవతలను వ్యతిరేకించిన గురువును కృష్ణుడు కీర్తించాడు. ఎవరైనా “వేరే పక్షాన” ఉన్నా వారి నైపుణ్యాన్ని గౌరవించగలమా?"]
},
{
 id: "sk-9", sage: "shukracharya", n: 9, order: 309, date: "2026-10-17",
 title: "The Bright Planet", titleTe: "ప్రకాశించే గ్రహం",
 src: "Purāṇas · Navagraha tradition",
 who: ["brihaspati", "shukracharya"],
 pages: [
  [
   ["p", "Look west just after sunset, or east just before dawn, and you may see the brightest point of light in the sky after the Sun and Moon — brighter than any star. That is Śukra, the planet Venus. Our tradition says it is the sage himself, shining among the nine grahas, the Navagrahas, that are honoured in temples across India.", "సూర్యాస్తమయం తర్వాత పడమర వైపు గానీ, తెల్లవారకముందు తూర్పు వైపు గానీ చూస్తే, సూర్యచంద్రుల తర్వాత ఆకాశంలో అత్యంత ప్రకాశవంతమైన వెలుగు కనిపించవచ్చు — ఏ నక్షత్రం కంటే ప్రకాశవంతమైనది. అదే శుక్రుడు — శుక్ర గ్రహం. భారతదేశమంతా దేవాలయాలలో పూజించే నవగ్రహాలలో ప్రకాశిస్తున్నది ఆ మహర్షే అని మన సంప్రదాయం చెబుతుంది."],
   ["p", "His old rival {brihaspati|Bṛhaspati} is there too, as Guru, the planet Jupiter. So the two classmates who taught the gods and the demons still sit side by side among the nine planets — and Friday (Śukravāram) and Thursday (Guruvāram) are named after them.", "ఆయన పాత ప్రత్యర్థి {brihaspati|బృహస్పతి} కూడా అక్కడే — గురు గ్రహంగా. అంటే దేవతలకూ రాక్షసులకూ బోధించిన ఆ ఇద్దరు సహపాఠులు ఇప్పటికీ నవగ్రహాలలో పక్కపక్కనే ఉన్నారు — శుక్రవారం, గురువారం వారి పేర్ల మీదే."]
  ],
  [
   ["p", "In the Navagraha tradition, Śukra is pictured as white and shining, seated on a white lotus or riding a white horse, holding a staff and a water-pot, with a rosary. His colour is white, his gem the diamond, his day Friday. The Navagraha Stotra attributed to Vyāsa praises him in one verse:", "నవగ్రహ సంప్రదాయంలో శుక్రుణ్ణి తెల్లగా, ప్రకాశిస్తూ, తెల్లని పద్మం మీద కూర్చుని గానీ తెల్ల గుర్రం మీద గానీ, దండం, కమండలం, జపమాల ధరించినవానిగా చిత్రిస్తారు. ఆయన రంగు తెలుపు, రత్నం వజ్రం, వారం శుక్రవారం. వ్యాసునిదిగా చెప్పే నవగ్రహ స్తోత్రం ఒక శ్లోకంలో ఆయనను కీర్తిస్తుంది:"],
   ["sloka", ["హిమకుందమృణాలాభం దైత్యానాం పరమం గురుమ్ ।", "సర్వశాస్త్రప్రవక్తారం భార్గవం ప్రణమామ్యహమ్ ॥"], ["himakunda-mṛṇālābhaṃ daityānāṃ paramaṃ gurum |", "sarva-śāstra-pravaktāraṃ bhārgavaṃ praṇamāmy aham ||"], "“White as snow, as jasmine and as the lotus stalk, the supreme guru of the daityas, the teacher of every science — I bow to Bhārgava, the son of Bhṛgu.”", "“మంచు, మల్లె, తామరతూడు వంటి తెల్లని కాంతి గలవాడు, దైత్యులకు పరమ గురువు, సర్వ శాస్త్రాలనూ బోధించేవాడు అయిన భార్గవునికి నమస్కరిస్తున్నాను.”"],
   ["dyk", "💍", "In Telugu homes you may have heard of “Śukra mauḍhyam” — the weeks each year when Venus is too close to the Sun to be seen. Traditionally, weddings and housewarmings are not held then, because Śukra, the planet of marriage and happiness, is “hidden.”", "తెలుగు ఇళ్ళలో “శుక్ర మౌఢ్యమి” గురించి వినే ఉంటారు — ప్రతి ఏటా శుక్రుడు సూర్యునికి చాలా దగ్గరగా ఉండి కనిపించని వారాలు. వివాహానికీ సుఖానికీ కారకుడైన శుక్రుడు “దాక్కుని” ఉంటాడు కాబట్టి సంప్రదాయంగా ఆ సమయంలో పెళ్ళిళ్ళు, గృహప్రవేశాలు చేయరు."]
  ],
  [
   ["h", "The Guru Who Never Left", "ఎప్పుడూ వదలని గురువు"],
   ["p", "What kind of sage was Śukrācārya? Not a gentle one like Vasiṣṭha. He was proud, fierce, and quick to curse — he cursed the asuras who doubted him, King Yayāti who broke his word, King Daṇḍa who wronged his daughter, and even Bali, his best disciple.", "శుక్రాచార్యుడు ఎలాంటి మహర్షి? వసిష్ఠునిలా సౌమ్యుడు కాదు. ఆత్మాభిమానం గలవాడు, ఉగ్రుడు, త్వరగా శపించేవాడు — తనను అనుమానించిన అసురులను, మాట తప్పిన యయాతిని, తన కూతురికి అన్యాయం చేసిన దండుని, తన ఉత్తమ శిష్యుడైన బలిని కూడా శపించాడు."],
   ["p", "But he was also the most loyal teacher in all the Purāṇas. He hung upside down for a thousand years to protect his students. He brought them back from death again and again. He taught even an enemy's son who came to him honestly, and gave him the secret when he had no choice. He loved his daughter more than his own pride. And in the end, standing before Viṣṇu, he bowed.", "కానీ పురాణాలన్నిటిలోనూ అత్యంత విశ్వాసపాత్రుడైన గురువు కూడా ఆయనే. శిష్యులను కాపాడడానికి వెయ్యేళ్ళు తలకిందులుగా వేలాడాడు. వారిని మళ్ళీ మళ్ళీ మృత్యువు నుండి వెనక్కి తెచ్చాడు. నిజాయితీగా వచ్చిన శత్రువు కొడుకుకు కూడా బోధించి, వేరే దారి లేనప్పుడు రహస్యాన్నే ఇచ్చేశాడు. తన ఆత్మాభిమానం కంటే కూతుర్ని ఎక్కువగా ప్రేమించాడు. చివరికి విష్ణువు ముందు నిలబడి నమస్కరించాడు."],
   ["p", "The gods had Bṛhaspati. The demons had Śukra. And Kṛṣṇa, who stands above both, said: among poets, I am Uśanā.", "దేవతలకు బృహస్పతి. రాక్షసులకు శుక్రుడు. ఇద్దరికీ అతీతుడైన శ్రీకృష్ణుడు అన్నాడు: కవులలో ఉశనుణ్ణి నేను."],
   ["dyk", "👁️", "In paintings and temple images Śukra is often shown with only one eye — a reminder of the story of Bali's water-pot.", "చిత్రాలలో, ఆలయ విగ్రహాలలో శుక్రుణ్ణి తరచూ ఒక్క కంటితోనే చూపిస్తారు — బలి కలశం కథకు గుర్తుగా."],
   ["src", "Navagraha Stotra (traditionally attributed to Vyāsa); Matsya Purāṇa and other Purāṇas on the Navagrahas. Śukra mauḍhyam is part of the Telugu pañcāṅga tradition.", "నవగ్రహ స్తోత్రం (సంప్రదాయంగా వ్యాసునిదిగా చెప్పబడుతుంది); నవగ్రహాల గురించి మత్స్య పురాణం, ఇతర పురాణాలు. శుక్ర మౌఢ్యమి తెలుగు పంచాంగ సంప్రదాయంలో భాగం."]
  ]
 ],
 remember: [
  ["Śukra is the planet Venus, one of the Navagrahas; Friday is his day.", "శుక్రుడు శుక్ర గ్రహం — నవగ్రహాలలో ఒకడు; శుక్రవారం ఆయన వారం."],
  ["His rival {brihaspati|Bṛhaspati} is Jupiter — they sit side by side among the nine planets.", "ఆయన ప్రత్యర్థి {brihaspati|బృహస్పతి} గురు గ్రహం — నవగ్రహాలలో ఇద్దరూ పక్కపక్కనే."],
  ["Fierce and quick to curse, he was also the most loyal of all teachers.", "ఉగ్రుడు, త్వరగా శపించేవాడు అయినా గురువులందరిలోనూ అత్యంత విశ్వాసపాత్రుడు."]
 ],
 think: ["Śukra and Bṛhaspati were rivals all their lives, yet they shine side by side. Is there someone you compete with whom you also respect?", "శుక్ర బృహస్పతులు జీవితమంతా ప్రత్యర్థులు; అయినా పక్కపక్కనే ప్రకాశిస్తున్నారు. మీరు పోటీ పడుతూనే గౌరవించే వ్యక్తి ఎవరైనా ఉన్నారా?"]
}
]);
